#[cfg(test)]
trait TestOwnerArgument {
    fn into_owner_argument(self) -> crate::types::KindedArgument;
}
#[cfg(test)]
impl TestOwnerArgument for Type {
    fn into_owner_argument(self) -> crate::types::KindedArgument {
        crate::types::KindedArgument::TypeArg(self)
    }
}
#[cfg(test)]
impl TestOwnerArgument for crate::types::KindedArgument {
    fn into_owner_argument(self) -> crate::types::KindedArgument {
        self
    }
}
#[cfg(test)]
fn replace_unary_interface_application(
    application: &mut InterfaceApplication,
    argument: impl TestOwnerArgument,
) {
    let replacement = InterfaceApplication::new_kinded(
        application.interface(),
        Box::new([argument.into_owner_argument()]),
    );
    drop(std::mem::replace(application, replacement));
}

#[cfg(test)]
fn replace_interface_application_identity(
    application: &mut InterfaceApplication,
    interface: InterfaceId,
) {
    let previous = std::mem::replace(
        application,
        InterfaceApplication::new(interface, Box::new([])),
    );
    let (_, arguments) = previous.into_parts();
    *application = InterfaceApplication::new_kinded(interface, arguments);
}

#[cfg(test)]
fn mutate_interface_application_arguments(
    application: &mut InterfaceApplication,
    mutate: impl FnOnce(&mut Vec<crate::types::KindedArgument>) -> bool,
) -> bool {
    let arguments = application.arguments_mut_for_summary_test();
    let mut arguments = std::mem::take(arguments).into_vec();
    let result = mutate(&mut arguments);
    *application.arguments_mut_for_summary_test() = arguments.into_boxed_slice();
    result
}

/// Stable identity of one resolved or compiler-generated term binder.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum BinderId {
    /// A source binder qualified by its defining canonical module.
    Resolved {
        /// Defining module identity.
        module: ModuleId,
        /// Source-order binder index within that module.
        local: u32,
    },
    /// A compiler-generated binder in the enclosing Core program.
    Generated(u32),
}

impl BinderId {
    /// Creates one compiler-generated binder identity.
    ///
    /// Retained as the compatibility spelling for Core fixture construction.
    pub(crate) const fn new(local: u32) -> Self {
        Self::generated(local)
    }

    pub(crate) const fn resolved(module: ModuleId, local: u32) -> Self {
        Self::Resolved { module, local }
    }

    pub(crate) const fn generated(local: u32) -> Self {
        Self::Generated(local)
    }

    /// Returns the defining module for a source binder.
    #[must_use]
    pub const fn module(self) -> Option<ModuleId> {
        match self {
            Self::Resolved { module, .. } => Some(module),
            Self::Generated(_) => None,
        }
    }

    /// Returns the module-local or generated-program-local index.
    #[must_use]
    pub const fn local(self) -> u32 {
        match self {
            Self::Resolved { local, .. } | Self::Generated(local) => local,
        }
    }
}

/// A resolved definition site.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Binder {
    /// Stable identity assigned by the resolver.
    pub id: BinderId,
    /// Exact source spelling.
    pub spelling: String,
    /// Causal source provenance for the definition site.
    pub origin: Origin,
}

/// A resolved occurrence site.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ResolvedOccurrence {
    /// Typed identity selected by lexical scope.
    pub term: ResolvedTermName,
    /// Exact source spelling at this occurrence.
    pub spelling: String,
    /// Causal source provenance for the occurrence site.
    pub origin: Origin,
    /// Exact direct import occurrence that introduced this term binding.
    pub(crate) import_span: Option<Span>,
    /// Atomic checked-goal and evidence positions owned by this exact occurrence.
    pub evidence: Box<[EvidenceSlot]>,
}

impl ResolvedOccurrence {
    /// Returns the ordinary binder selected by this occurrence, if it is not a method.
    #[must_use]
    pub const fn global_binder(&self) -> Option<BinderId> {
        match self.term {
            ResolvedTermName::Global(binder) => Some(binder),
            ResolvedTermName::Method(_) => None,
        }
    }

    /// Returns the direct import occurrence that introduced this binding.
    #[must_use]
    pub const fn import_span(&self) -> Option<Span> {
        self.import_span
    }
}

/// The tagged semantic identity of one resolved term occurrence.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum ResolvedTermName {
    /// An ordinary global or lexical binder.
    Global(BinderId),
    /// An interface method requiring evidence during checking.
    Method(MethodId),
}

/// A repeated equation-head occurrence, which never owns evidence.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ResolvedEquationHead {
    /// Stable identity of the ordinary or hidden binder being defined.
    pub binder: BinderId,
    /// Exact source spelling at the repeated head.
    pub spelling: String,
    /// Causal source provenance for the head occurrence.
    pub origin: Origin,
}

/// Cross-family declaration order with category-local indices.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ResolvedDeclarationIndex {
    /// An experimental provider assembly.
    Resource(usize),
    /// A product source resource assembly.
    SourceResource(usize),
    /// A nominal type declaration.
    Type(usize),
    /// An interface declaration.
    Interface(usize),
    /// An effect declaration.
    Effect(usize),
    /// An ordinary global definition.
    Global(usize),
    /// An implementation declaration.
    Implementation(usize),
}

/// One resolver-authenticated source edge to a direct dependency.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DirectDependencyRoute {
    target: ModuleId,
    import_span: Span,
}

impl DirectDependencyRoute {
    pub(crate) const fn new(target: ModuleId, import_span: Span) -> Self {
        Self {
            target,
            import_span,
        }
    }

    /// Returns the canonical identity reached by this direct edge.
    #[must_use]
    pub const fn target(self) -> ModuleId {
        self.target
    }

    /// Returns the exact source import occurrence that introduced this edge.
    #[must_use]
    pub const fn import_span(self) -> Span {
        self.import_span
    }
}

/// One declarations-only module after name resolution.
#[derive(Debug, Eq, PartialEq)]
pub struct ResolvedModule {
    module: ModuleId,
    registry: Arc<ResolvedRegistry>,
    imported: ImportedFacts,
    direct_dependencies: Box<[DirectDependencyRoute]>,
    declaration_order: Box<[ResolvedDeclarationIndex]>,
    interfaces: Box<[ResolvedInterfaceDeclaration]>,
    effects: Box<[ResolvedEffectDeclaration]>,
    implementations: Box<[ResolvedImplementation]>,
    definitions: Box<[ResolvedDefinition]>,
    export_candidate: ResolvedExportCandidate,
    resources: Box<[ResolvedResourceDefinition]>,
    source_resources: Box<[ResolvedSourceResourceDefinition]>,
    span: Span,
    defining_sources: Vec<(ModuleId, Arc<crate::source::SourceFile>)>,
}

pub(crate) struct ResolvedModuleParts {
    pub module: ModuleId,
    pub registry: Arc<ResolvedRegistry>,
    pub imported: ImportedFacts,
    pub direct_dependencies: Vec<DirectDependencyRoute>,
    pub declaration_order: Vec<ResolvedDeclarationIndex>,
    pub interfaces: Vec<ResolvedInterfaceDeclaration>,
    pub effects: Vec<ResolvedEffectDeclaration>,
    pub implementations: Vec<ResolvedImplementation>,
    pub definitions: Vec<ResolvedDefinition>,
    pub export_candidate: ResolvedExportCandidate,
    pub resources: Vec<ResolvedResourceDefinition>,
    pub source_resources: Vec<ResolvedSourceResourceDefinition>,
    pub span: Span,
}

impl ResolvedModule {
    pub(crate) fn authenticate_owner_definitions(
        &self,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        self.registry.authenticate_owner_signature_coverage(
            self.effects
                .iter()
                .map(|effect| OwnerId::Effect(effect.id))
                .chain(
                    self.interfaces
                        .iter()
                        .map(|interface| OwnerId::Interface(interface.id)),
                )
                .chain(
                    self.resources
                        .iter()
                        .map(|resource| OwnerId::Resource(resource.id)),
                )
                .chain(
                    self.source_resources
                        .iter()
                        .map(|resource| OwnerId::Resource(resource.id)),
                ),
            budget,
        )?;
        for effect in &self.effects {
            budget
                .charge(1)
                .map_err(|()| ResolvedBuildFailure::TypeResource)?;
            let canonical = self
                .registry
                .effect(effect.id)
                .ok_or(ResolvedBuildFailure::InvalidState)?;
            match (&effect.native_contract, &canonical.native_contract) {
                (None, None) => {}
                (Some(local), Some(original))
                    if Arc::ptr_eq(local, original) && local.effect() == effect.id => {}
                _ => return Err(ResolvedBuildFailure::InvalidState),
            }
            self.registry.authenticate_owner_signature(
                OwnerId::Effect(effect.id),
                None,
                &effect.parameters,
                budget,
            )?;
        }
        for interface in &self.interfaces {
            self.registry.authenticate_owner_signature(
                OwnerId::Interface(interface.id),
                None,
                &interface.parameters,
                budget,
            )?;
        }
        for resource in &self.source_resources {
            self.registry.authenticate_owner_signature(
                OwnerId::Resource(resource.id),
                Some(resource.family),
                &resource.parameters,
                budget,
            )?;
        }
        for resource in &self.resources {
            self.registry.authenticate_owner_signature(
                OwnerId::Resource(resource.id),
                Some(resource.family),
                &resource.parameters,
                budget,
            )?;
            if let Some(family) = &resource.family_template {
                self.registry.authenticate_resource_family_parameter(
                    &family.parameter,
                    &resource.parameters,
                    &resource.answer,
                    budget,
                )?;
            }
        }
        Ok(())
    }

    pub(crate) fn new(mut parts: ResolvedModuleParts) -> Self {
        Self {
            module: parts.module,
            registry: std::mem::take(&mut parts.registry),
            imported: std::mem::take(&mut parts.imported),
            direct_dependencies: std::mem::take(&mut parts.direct_dependencies).into_boxed_slice(),
            declaration_order: std::mem::take(&mut parts.declaration_order).into_boxed_slice(),
            interfaces: std::mem::take(&mut parts.interfaces).into_boxed_slice(),
            effects: std::mem::take(&mut parts.effects).into_boxed_slice(),
            implementations: std::mem::take(&mut parts.implementations).into_boxed_slice(),
            definitions: std::mem::take(&mut parts.definitions).into_boxed_slice(),
            resources: std::mem::take(&mut parts.resources).into_boxed_slice(),
            source_resources: std::mem::take(&mut parts.source_resources).into_boxed_slice(),
            export_candidate: std::mem::take(&mut parts.export_candidate),
            span: parts.span,
            defining_sources: Vec::new(),
        }
    }

    pub(crate) fn retain_defining_sources<'a>(
        &mut self,
        local: &Arc<crate::source::SourceFile>,
        dependencies: impl Iterator<Item = &'a ExportSummary>,
        work: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        if !self.defining_sources.is_empty() || local.id() != self.span.source() {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        let mut retained = Vec::new();
        work.charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        retained
            .try_reserve(1)
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        retained.push((self.module, Arc::clone(local)));
        let mut positions = HashMap::new();
        work.charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        positions
            .try_reserve(1)
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        positions.insert(self.module, 0);
        for dependency in dependencies {
            for (module, source) in &dependency.defining_sources {
                work.charge(1)
                    .map_err(|()| ResolvedBuildFailure::TypeResource)?;
                if let Some(position) = positions.get(module) {
                    if !Arc::ptr_eq(&retained[*position].1, source) {
                        work.charge(
                            retained[*position]
                                .1
                                .snapshot_work()
                                .map_err(|()| ResolvedBuildFailure::TypeResource)?
                                .checked_add(
                                    source
                                        .snapshot_work()
                                        .map_err(|()| ResolvedBuildFailure::TypeResource)?,
                                )
                                .ok_or(ResolvedBuildFailure::TypeResource)?,
                        )
                        .map_err(|()| ResolvedBuildFailure::TypeResource)?;
                        if retained[*position].1 != *source {
                            return Err(ResolvedBuildFailure::InvalidState);
                        }
                    }
                    continue;
                }
                work.charge(2)
                    .map_err(|()| ResolvedBuildFailure::TypeResource)?;
                retained
                    .try_reserve(1)
                    .map_err(|_| ResolvedBuildFailure::TypeResource)?;
                positions
                    .try_reserve(1)
                    .map_err(|_| ResolvedBuildFailure::TypeResource)?;
                positions.insert(*module, retained.len());
                retained.push((*module, Arc::clone(source)));
            }
        }
        self.defining_sources = retained;
        Ok(())
    }

    pub(crate) fn defining_sources(&self) -> &[(ModuleId, Arc<crate::source::SourceFile>)] {
        &self.defining_sources
    }

    /// Returns the defining canonical module identity.
    #[must_use]
    pub const fn module(&self) -> ModuleId {
        self.module
    }
    /// Returns the module's resolved local registry.
    #[must_use]
    pub fn registry(&self) -> &Arc<ResolvedRegistry> {
        &self.registry
    }

    /// Returns selected, body-free facts cloned from dependency summaries.
    #[must_use]
    pub const fn imported_facts(&self) -> &ImportedFacts {
        &self.imported
    }

    /// Returns the authenticated direct dependency edges in source order.
    #[must_use]
    pub const fn direct_dependencies(&self) -> &[DirectDependencyRoute] {
        &self.direct_dependencies
    }

    /// Returns the explicit cross-family declaration order.
    #[must_use]
    pub const fn declaration_order(&self) -> &[ResolvedDeclarationIndex] {
        &self.declaration_order
    }

    /// Returns local interface declarations in category-local source order.
    #[must_use]
    pub const fn interfaces(&self) -> &[ResolvedInterfaceDeclaration] {
        &self.interfaces
    }

    /// Returns local effect declarations in category-local source order.
    #[must_use]
    pub const fn effects(&self) -> &[ResolvedEffectDeclaration] {
        &self.effects
    }

    /// Returns local implementation declarations in category-local source order.
    #[must_use]
    pub const fn implementations(&self) -> &[ResolvedImplementation] {
        &self.implementations
    }

    /// Returns experimental resource templates in defining declaration order.
    #[must_use]
    pub fn resources(&self) -> &[ResolvedResourceDefinition] {
        &self.resources
    }

    #[cfg(test)]
    pub(crate) fn replace_provider_handler_body_span_for_test(&mut self, span: Span) {
        self.resources
            .last_mut()
            .expect("provider declaration")
            .handlers
            .last_mut()
            .expect("provider clause")
            .body
            .span = span;
    }

    /// Returns product source resource templates in declaration order.
    #[must_use]
    pub fn source_resources(&self) -> &[ResolvedSourceResourceDefinition] {
        &self.source_resources
    }

    /// Looks up one local product source resource definition.
    #[must_use]
    pub fn source_resource(
        &self,
        id: ResourceDefinitionId,
    ) -> Option<&ResolvedSourceResourceDefinition> {
        self.source_resources
            .iter()
            .find(|resource| resource.id == id)
    }

    /// Looks up one local experimental resource definition.
    #[must_use]
    pub fn resource(&self, id: ResourceDefinitionId) -> Option<&ResolvedResourceDefinition> {
        self.resources.iter().find(|resource| resource.id == id)
    }

    /// Returns local definitions in source order.
    #[must_use]
    pub fn definitions(&self) -> &[ResolvedDefinition] {
        &self.definitions
    }

    fn take_interfaces(&mut self) -> Box<[ResolvedInterfaceDeclaration]> {
        std::mem::take(&mut self.interfaces)
    }

    fn take_effects(&mut self) -> Box<[ResolvedEffectDeclaration]> {
        std::mem::take(&mut self.effects)
    }

    /// Moves resolved globals across a successful checker-owned transition.
    pub(crate) fn take_definitions(&mut self) -> Box<[ResolvedDefinition]> {
        std::mem::take(&mut self.definitions)
    }

    /// Moves resolved implementation bodies across a successful checker-owned transition.
    pub(crate) fn take_implementations(&mut self) -> Box<[ResolvedImplementation]> {
        std::mem::take(&mut self.implementations)
    }

    /// Returns the unchecked set of local declarations eligible for export.
    #[must_use]
    pub const fn export_candidate(&self) -> &ResolvedExportCandidate {
        &self.export_candidate
    }

    /// Returns the complete accepted module span.
    #[must_use]
    pub const fn span(&self) -> Span {
        self.span
    }

    #[cfg(test)]
    pub(crate) fn replace_local_constructor_payload_for_test(
        &mut self,
        id: ConstructorId,
        payload: Type,
    ) -> bool {
        let payload = IterativeTypeOwner::new(payload);
        let Some(registry) = Arc::get_mut(&mut self.registry) else {
            return false;
        };
        let Some(constructor) = registry
            .constructors
            .iter_mut()
            .find(|constructor| constructor.id == id)
        else {
            return false;
        };
        if let Some(displaced) = constructor.payload.replace(payload.into_inner()) {
            discard_type_iteratively(displaced);
        }
        true
    }
}

impl Drop for ResolvedModuleParts {
    fn drop(&mut self) {
        for resource in self.source_resources.drain(..) {
            discard_resolved_source_resource_definition(resource);
        }
        for resource in self.resources.drain(..) {
            discard_resolved_resource_definition(resource);
        }
        for interface in self.interfaces.drain(..) {
            discard_resolved_interface_iteratively(interface);
        }
        for effect in self.effects.drain(..) {
            discard_resolved_effect_iteratively(effect);
        }
        for definition in self.definitions.drain(..) {
            discard_resolved_definition_iteratively(definition);
        }
        for implementation in self.implementations.drain(..) {
            discard_resolved_implementation_iteratively(implementation);
        }
    }
}

impl Drop for ResolvedModule {
    fn drop(&mut self) {
        for resource in std::mem::take(&mut self.source_resources).into_vec() {
            discard_resolved_source_resource_definition(resource);
        }
        for resource in std::mem::take(&mut self.resources).into_vec() {
            discard_resolved_resource_definition(resource);
        }
        for interface in self.take_interfaces().into_vec() {
            discard_resolved_interface_iteratively(interface);
        }
        for effect in self.take_effects().into_vec() {
            discard_resolved_effect_iteratively(effect);
        }
        for definition in self.take_definitions().into_vec() {
            discard_resolved_definition_iteratively(definition);
        }
        for implementation in self.take_implementations().into_vec() {
            discard_resolved_implementation_iteratively(implementation);
        }
    }
}

/// One fully checked local global scheme retained for linking and exports.
#[derive(Debug, Eq, PartialEq)]
pub struct CheckedGlobalScheme {
    pub(crate) capture: crate::core::capture::CaptureValueSummary,
    /// Stable binder identity.
    pub binder: BinderId,
    /// Source declaration spelling.
    pub spelling: String,
    /// Closed, inference-free constrained rank-1 scheme.
    pub scheme: ConstrainedScheme,
    /// Causal declaration provenance.
    pub origin: Origin,
}

impl Drop for CheckedGlobalScheme {
    fn drop(&mut self) {
        let span = self.origin.primary_span();
        discard_origin_iteratively(std::mem::replace(&mut self.origin, Origin::Source(span)));
    }
}

/// Body-free completed facts used by provider entries before the defining
/// module's single publication commit. Lowered ABI and source bodies are absent.
#[derive(Debug)]
pub(crate) struct ProviderDefiningFacts {
    pub(crate) globals: Vec<ProviderDefiningGlobal>,
    pub(crate) positions: HashMap<BinderId, usize>,
    pub(crate) interfaces: Vec<CheckedInterfaceFact>,
    pub(crate) implementations: Vec<CheckedImplementationFact>,
}
#[derive(Debug)]
pub(crate) struct ProviderDefiningGlobal {
    pub(crate) binder: BinderId,
    pub(crate) scheme: ConstrainedScheme,
    pub(crate) capture: crate::core::capture::CaptureValueSummary,
    pub(crate) origin: crate::core::provider::RetainedHandlerOrigin,
}
impl ProviderDefiningFacts {
    pub(crate) fn global(&self, binder: BinderId) -> Option<&ProviderDefiningGlobal> {
        self.globals.get(*self.positions.get(&binder)?)
    }
}
/// Borrowed original imported or completed defining fact, with no counterfeit
/// import authorization and no source expression or executable projection.
#[derive(Clone, Copy)]
pub(crate) enum ProviderGlobalFact<'a> {
    Imported(&'a ImportedGlobalScheme),
    Defining(&'a ProviderDefiningGlobal),
}
impl<'a> ProviderGlobalFact<'a> {
    pub(crate) fn binder(self) -> BinderId {
        match self {
            Self::Imported(fact) => fact.binder,
            Self::Defining(fact) => fact.binder,
        }
    }
    pub(crate) fn scheme(self) -> &'a ConstrainedScheme {
        match self {
            Self::Imported(fact) => &fact.scheme,
            Self::Defining(fact) => &fact.scheme,
        }
    }
    pub(crate) fn capture(self) -> &'a crate::core::capture::CaptureValueSummary {
        match self {
            Self::Imported(fact) => &fact.capture,
            Self::Defining(fact) => &fact.capture,
        }
    }
    pub(crate) fn origin(self) -> &'a Origin {
        match self {
            Self::Imported(fact) => &fact.origin,
            Self::Defining(fact) => fact.origin.as_origin(),
        }
    }
}
#[derive(Clone, Copy)]
pub(crate) struct ProviderExternalFacts<'a> {
    pub(crate) imported: &'a ImportedFacts,
    pub(crate) defining: Option<&'a ProviderDefiningFacts>,
}
impl<'a> ProviderExternalFacts<'a> {
    pub(crate) fn interface(
        self,
        id: InterfaceId,
        work: &mut TypeWorkBudget,
    ) -> Result<Option<&'a CheckedInterfaceFact>, ()> {
        if let Some(fact) = self.imported.interface(id) {
            return Ok(Some(fact));
        }
        if let Some(defining) = self.defining {
            work.charge(defining.interfaces.len())?;
            return Ok(defining.interfaces.iter().find(|fact| fact.id == id));
        }
        Ok(None)
    }
    pub(crate) fn implementation(
        self,
        id: ImplId,
        work: &mut TypeWorkBudget,
    ) -> Result<Option<&'a CheckedImplementationFact>, ()> {
        if let Some(fact) = self.imported.implementation(id) {
            return Ok(Some(fact));
        }
        if let Some(defining) = self.defining {
            work.charge(defining.implementations.len())?;
            return Ok(defining.implementations.iter().find(|fact| fact.id == id));
        }
        Ok(None)
    }
    pub(crate) fn global(self, binder: BinderId) -> Option<ProviderGlobalFact<'a>> {
        self.imported
            .global(binder)
            .map(ProviderGlobalFact::Imported)
            .or_else(|| {
                self.defining
                    .and_then(|facts| facts.global(binder))
                    .map(ProviderGlobalFact::Defining)
            })
    }
    pub(crate) fn globals(self) -> impl Iterator<Item = ProviderGlobalFact<'a>> {
        self.imported
            .globals()
            .map(ProviderGlobalFact::Imported)
            .chain(
                self.defining
                    .into_iter()
                    .flat_map(|facts| facts.globals.iter().map(ProviderGlobalFact::Defining)),
            )
    }
}

/// One resolved global definition admitted by successful body checking.
///
/// The private source field prevents callers from presenting an unchecked
/// [`ResolvedDefinition`] at the checked-module boundary.
#[derive(Debug)]
pub struct CheckedDefinition {
    source: Option<ResolvedDefinition>,
}

impl CheckedDefinition {
    pub(crate) fn new(source: ResolvedDefinition) -> Self {
        Self {
            source: Some(source),
        }
    }

    /// Returns the checked definition family without granting mutation.
    #[must_use]
    pub fn kind(&self) -> &ResolvedDefinitionKind {
        &self
            .source
            .as_ref()
            .expect("a checked definition retains its source")
            .kind
    }

    /// Returns the complete checked definition span.
    #[must_use]
    pub fn span(&self) -> Span {
        self.source
            .as_ref()
            .expect("a checked definition retains its source")
            .span
    }
}

impl Drop for CheckedDefinition {
    fn drop(&mut self) {
        if let Some(source) = self.source.take() {
            discard_resolved_definition_iteratively(source);
        }
    }
}

