impl Drop for ResolvedModuleProgram {
    fn drop(&mut self) {
        let placeholder = ResolvedExpr {
            kind: ResolvedExprKind::Unit,
            span: self.result.span,
        };
        let result = std::mem::replace(&mut self.result, placeholder);
        discard_resolved_body_work(vec![result], Vec::new());
    }
}

fn retain_native_symbols(
    target: &mut HashMap<OperationId, Arc<crate::foreign::checked_source::CheckedForeignSymbol>>,
    source: &HashMap<OperationId, Arc<crate::foreign::checked_source::CheckedForeignSymbol>>,
    work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    work.charge(source.len())
        .map_err(|()| ResolvedBuildFailure::TypeResource)?;
    target
        .try_reserve(source.len())
        .map_err(|_| ResolvedBuildFailure::TypeResource)?;
    for (id, symbol) in source {
        match target.entry(*id) {
            std::collections::hash_map::Entry::Vacant(entry) => {
                entry.insert(Arc::clone(symbol));
            }
            std::collections::hash_map::Entry::Occupied(entry)
                if Arc::ptr_eq(entry.get(), symbol) => {}
            _ => return Err(ResolvedBuildFailure::InvalidState),
        }
    }
    Ok(())
}

fn scalar_preflight_failure(
    failure: crate::foreign::checked_source::ForeignAdmissionError,
) -> ResolvedBuildFailure {
    if failure.is_resource_exhaustion() {
        ResolvedBuildFailure::TypeResource
    } else {
        ResolvedBuildFailure::InvalidState
    }
}

fn same_scalar_preflight(
    left: Option<&Arc<crate::foreign::scalar_preflight::CheckedForeignScalarPreflight>>,
    right: Option<&Arc<crate::foreign::scalar_preflight::CheckedForeignScalarPreflight>>,
) -> bool {
    match (left, right) {
        (None, None) => true,
        (Some(left), Some(right)) => Arc::ptr_eq(left, right),
        _ => false,
    }
}

fn retain_scalar_preflights(
    target: &mut HashMap<
        BinderId,
        Arc<crate::foreign::scalar_preflight::CheckedForeignScalarPreflight>,
    >,
    source: &HashMap<
        BinderId,
        Arc<crate::foreign::scalar_preflight::CheckedForeignScalarPreflight>,
    >,
    work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    work.charge(source.len())
        .map_err(|()| ResolvedBuildFailure::TypeResource)?;
    target
        .try_reserve(source.len())
        .map_err(|_| ResolvedBuildFailure::TypeResource)?;
    for (function, fact) in source {
        if *function != fact.function() {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        match target.entry(*function) {
            std::collections::hash_map::Entry::Vacant(entry) => {
                entry.insert(Arc::clone(fact));
            }
            std::collections::hash_map::Entry::Occupied(entry)
                if Arc::ptr_eq(entry.get(), fact) => {}
            _ => return Err(ResolvedBuildFailure::InvalidState),
        }
    }
    Ok(())
}

fn retain_shared_source_nominal(
    target: &mut HashMap<NominalTypeId, crate::foreign::source_access::CheckedForeignNominal>,
    fact: crate::foreign::source_access::CheckedForeignNominal,
    work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    if let Some(original) = target.get(&fact.nominal()) {
        if !original.same_original(&fact) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    } else {
        work.charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        target
            .try_reserve(1)
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        target.insert(fact.nominal(), fact);
    }
    Ok(())
}
fn retain_shared_source_owner(
    target: &mut HashMap<NominalTypeId, crate::foreign::source_access::CheckedForeignNominal>,
    owner: &Arc<crate::foreign::source_owner::CheckedForeignOwner>,
    work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    retain_shared_source_nominal(
        target,
        crate::foreign::source_access::CheckedForeignNominal::Owner(Arc::clone(owner)),
        work,
    )
}

/// Body-free dependency facts retained by one resolved module.
#[derive(Debug, Default, Eq, PartialEq)]
pub struct ImportedFacts {
    globals: HashMap<BinderId, ImportedGlobalScheme>,
    global_order: Vec<BinderId>,
    nominals: HashMap<NominalTypeId, ImportedNominalFact>,
    nominal_order: Vec<NominalTypeId>,
    /// Canonical representations retained for opaque linkage only. Source-facing
    /// imported nominal facts intentionally do not expose these templates.
    canonical_representations: HashMap<NominalTypeId, CanonicalRepresentationFact>,
    foreign_modules: std::collections::BTreeMap<ModuleId, Arc<crate::foreign::ForeignModuleFact>>,
    native_symbols: HashMap<OperationId, Arc<crate::foreign::checked_source::CheckedForeignSymbol>>,
    /// Exact admitted nominal category retained without selecting a native operation.
    source_owners: HashMap<NominalTypeId, crate::foreign::source_access::CheckedForeignNominal>,
    provider_groups: std::collections::BTreeMap<
        ModuleId,
        Arc<crate::elaborate::provider::CheckedProviderContracts>,
    >,
    resource_facts: HashMap<NominalTypeId, (String, Arc<ResourceTypeFact>)>,
    resource_fact_order: Vec<NominalTypeId>,
    resource_types: HashMap<String, Arc<ResourceTypeFact>>,
    resource_type_order: Vec<String>,
    constructors: HashMap<ConstructorId, ImportedConstructorFact>,
    interfaces: Vec<ImportedInterfaceFact>,
    interface_positions: HashMap<InterfaceId, usize>,
    effects: Vec<ResolvedEffectDeclaration>,
    effect_positions: HashMap<EffectId, usize>,
    implementations: Vec<ImportedImplementationFact>,
    implementation_positions: HashMap<ImplId, usize>,
    /// Passive declaration census; it selects no implementation evidence.
    implemented_interfaces: HashSet<InterfaceId>,
    public_implementation_order: Vec<ImplId>,
    source_resource_facts: HashMap<ResourceDefinitionId, Arc<SourceResourceTypeFact>>,
    source_resource_types: HashMap<String, Arc<SourceResourceTypeFact>>,
    source_resource_type_order: Vec<String>,
}

/// Canonical representation authority retained for opaque linking.
#[derive(Debug, Eq, PartialEq)]
pub(crate) struct CanonicalRepresentationFact {
    pub(crate) representation: Type,
    pub(crate) provenance: ResolvedTypeProvenance,
}

fn discard_canonical_representation_fact(fact: CanonicalRepresentationFact) {
    discard_type_iteratively(fact.representation);
    drop(fact.provenance);
}

impl ImportedFacts {
    /// Borrows the original admitted provider certificate for compiler-only
    /// preparation. Availability does not grant executable Core authority.
    pub(crate) fn provider_contract(
        &self,
        module: ModuleId,
    ) -> Option<&Arc<crate::elaborate::provider::CheckedProviderContracts>> {
        self.provider_groups.get(&module)
    }

    pub(crate) fn foreign_state_access_interface(&self, id: crate::interface::InterfaceId) -> bool {
        self.foreign_modules
            .values()
            .filter_map(|module| module.state_access.as_ref())
            .any(|access| access.interface == id)
    }

    pub(crate) fn foreign_layout_interface(&self, id: crate::interface::InterfaceId) -> bool {
        self.foreign_modules
            .values()
            .filter_map(|module| module.layout.as_ref())
            .any(|layout| layout.interface() == id)
    }

    pub(crate) fn retain_provider_contracts(
        &mut self,
        summary: &ExportSummary,
        work: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        work.charge(summary.provider_groups.len())
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        for (module, contracts) in &summary.provider_groups {
            match self.provider_groups.entry(*module) {
                std::collections::btree_map::Entry::Occupied(existing) => {
                    if !Arc::ptr_eq(existing.get(), contracts) {
                        return Err(ResolvedBuildFailure::InvalidState);
                    }
                }
                std::collections::btree_map::Entry::Vacant(slot) => {
                    slot.insert(Arc::clone(contracts));
                }
            }
        }
        Ok(())
    }

    pub(crate) fn retain_foreign(
        &mut self,
        summary: &ExportSummary,
        _work: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        // Native descriptors follow selected effect facts in insert_effect, rather
        // than bringing every unselected public operation into the importing registry.
        for (id, fact) in &summary.foreign_modules {
            if let Some(existing) = self.foreign_modules.get(id)
                && !Arc::ptr_eq(existing, fact)
                && existing != fact
            {
                return Err(ResolvedBuildFailure::InvalidState);
            }
            self.foreign_modules.insert(*id, Arc::clone(fact));
        }
        Ok(())
    }

    fn into_effects(mut self) -> Box<[ResolvedEffectDeclaration]> {
        let effects = std::mem::take(&mut self.effects);
        effects.into_boxed_slice()
    }

    /// Looks up one imported checked global by semantic identity.
    #[must_use]
    pub fn global(&self, id: BinderId) -> Option<&ImportedGlobalScheme> {
        self.globals.get(&id)
    }

    pub(crate) fn retain_summary_source_owner(
        &mut self,
        summary: &ExportSummary,
        nominal: NominalTypeId,
        work: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        let fact = summary
            .nominal_fact(nominal)
            .ok_or(ResolvedBuildFailure::InvalidState)?;
        if fact.constructor_count != 0 {
            return Ok(());
        }
        work.charge(1)
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        let owner = summary
            .source_owners
            .get(&nominal)
            .ok_or(ResolvedBuildFailure::InvalidState)?;
        fact.authenticate_source_foreign_nominal(owner, work)?;
        if let Some(existing) = self.source_owners.get(&nominal) {
            if !existing.same_original(owner) {
                return Err(ResolvedBuildFailure::InvalidState);
            }
        } else {
            work.charge(1)
                .map_err(|_| ResolvedBuildFailure::TypeResource)?;
            self.source_owners
                .try_reserve(1)
                .map_err(|_| ResolvedBuildFailure::TypeResource)?;
            self.source_owners
                .entry(nominal)
                .or_insert_with(|| owner.clone());
        }
        Ok(())
    }

    pub(crate) fn source_access(
        &self,
        id: NominalTypeId,
    ) -> Option<&Arc<crate::foreign::source_access::CheckedForeignAccess>> {
        match self.source_owners.get(&id)? {
            crate::foreign::source_access::CheckedForeignNominal::Access(access) => Some(access),
            crate::foreign::source_access::CheckedForeignNominal::Owner(_) => None,
        }
    }

    pub(crate) fn source_owner(
        &self,
        id: NominalTypeId,
    ) -> Option<&Arc<crate::foreign::source_owner::CheckedForeignOwner>> {
        match self.source_owners.get(&id)? {
            crate::foreign::source_access::CheckedForeignNominal::Owner(owner) => Some(owner),
            crate::foreign::source_access::CheckedForeignNominal::Access(_) => None,
        }
    }

    /// Looks up one imported nominal fact by semantic identity.
    #[must_use]
    pub fn nominal(&self, id: NominalTypeId) -> Option<&ImportedNominalFact> {
        self.nominals.get(&id)
    }

    /// Canonical linkage view; never use this to grant source constructor access.
    pub(crate) fn canonical_nominal_fact(
        &self,
        id: NominalTypeId,
    ) -> Option<ImportedNominalFactRef<'_>> {
        let fact = self.nominal(id)?;
        let canonical = self.canonical_representation(id);
        Some(ImportedNominalFactRef {
            id: fact.id,
            declaration_kind: fact.declaration_kind,
            parameter_count: fact.parameter_count,
            constructor_count: fact.constructor_count,
            parameters: &fact.parameters,
            representation: fact
                .representation
                .as_ref()
                .or_else(|| canonical.map(|fact| &fact.representation)),
            representation_provenance: fact
                .representation_provenance
                .as_ref()
                .or_else(|| canonical.map(|fact| &fact.provenance)),
            constructors: &fact.constructors,
            access: fact.access,
            display_spelling: fact.display_spelling.as_deref(),
            display_is_private: fact.display_is_private,
            origin: &fact.origin,
        })
    }

    pub(crate) fn canonical_representation(
        &self,
        id: NominalTypeId,
    ) -> Option<&CanonicalRepresentationFact> {
        self.canonical_representations.get(&id)
    }

    pub(crate) fn retain_canonical_representation(
        &mut self,
        id: NominalTypeId,
        representation: &Type,
        provenance: &ResolvedTypeProvenance,
        type_work: &mut TypeWorkBudget,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<(), ImportedNominalMergeFailure> {
        if let Some(existing) = self.canonical_representations.get(&id) {
            if !same_type_with_constraint_budget(
                &existing.representation,
                representation,
                constraint_work,
            )
            .map_err(|_| ImportedNominalMergeFailure::ConstraintResource)?
                || !same_resolved_type_provenance_with_constraint_budget(
                    &existing.provenance,
                    provenance,
                    constraint_work,
                )
                .map_err(|_| ImportedNominalMergeFailure::ConstraintResource)?
            {
                return Err(ImportedNominalMergeFailure::Conflict);
            }
            return Ok(());
        }
        type_work
            .charge(1)
            .map_err(|()| ImportedNominalMergeFailure::TypeResource)?;
        self.canonical_representations
            .try_reserve(1)
            .map_err(|_| ImportedNominalMergeFailure::TypeResource)?;
        let retained = CanonicalRepresentationFact {
            representation: clone_type_with_budget(representation, type_work)
                .map_err(|()| ImportedNominalMergeFailure::TypeResource)?,
            provenance: provenance.clone(),
        };
        if let Some(displaced) = self.canonical_representations.insert(id, retained) {
            discard_canonical_representation_fact(displaced);
            return Err(ImportedNominalMergeFailure::Conflict);
        }
        Ok(())
    }

    /// Looks up one imported transparent constructor by semantic identity.
    #[must_use]
    pub fn constructor(&self, id: ConstructorId) -> Option<&ImportedConstructorFact> {
        self.constructors.get(&id)
    }

    /// Looks up one imported checked interface by semantic identity.
    #[must_use]
    pub fn interface(&self, id: InterfaceId) -> Option<&CheckedInterfaceFact> {
        Some(
            &self
                .interfaces
                .get(*self.interface_positions.get(&id)?)?
                .fact,
        )
    }

    pub(crate) fn shared_interface(&self, id: InterfaceId) -> Option<&SharedCheckedInterfaceFact> {
        self.interfaces
            .get(*self.interface_positions.get(&id)?)
            .map(|imported| &imported.fact)
    }

    /// Looks up one imported canonical effect fact by identity.
    #[must_use]
    pub fn effect(&self, id: EffectId) -> Option<&ResolvedEffectDeclaration> {
        self.effects.get(*self.effect_positions.get(&id)?)
    }

    pub(crate) fn effects(&self) -> impl Iterator<Item = &ResolvedEffectDeclaration> {
        self.effects.iter()
    }

    pub(crate) fn insert_effect(
        &mut self,
        fact: ResolvedEffectDeclaration,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ()> {
        let position = self.effect_positions.get(&fact.id).copied();
        let admission = (|| {
            budget.charge(1)?;
            if let Some(position) = position {
                let existing = self.effects.get(position).ok_or(())?;
                match (&existing.native_contract, &fact.native_contract) {
                    (None, None) => {}
                    (Some(original), Some(incoming)) if Arc::ptr_eq(original, incoming) => {}
                    _ => return Err(()),
                }
            } else {
                budget.charge(2)?;
                self.effects.try_reserve(1).map_err(|_| ())?;
                self.effect_positions.try_reserve(1).map_err(|_| ())?;
            }
            if let Some(symbol) = &fact.native_contract {
                if symbol.effect() != fact.id {
                    return Err(());
                }
                budget.charge(1)?;
                self.native_symbols.try_reserve(1).map_err(|_| ())?;
                if self
                    .native_symbols
                    .get(&symbol.operation())
                    .is_some_and(|original| !Arc::ptr_eq(original, symbol))
                {
                    return Err(());
                }
            } else if self
                .native_symbols
                .contains_key(&OperationId::new(fact.id, 0))
            {
                return Err(());
            }
            Ok(())
        })();
        if admission.is_err() {
            discard_resolved_effect_iteratively(fact);
            return Err(());
        }
        if let Some(symbol) = &fact.native_contract
            && let std::collections::hash_map::Entry::Vacant(entry) =
                self.native_symbols.entry(symbol.operation())
        {
            entry.insert(Arc::clone(symbol));
        }
        if let Some(position) = position {
            let existing = self
                .effects
                .get_mut(position)
                .expect("effect replacement position was admitted before publication");
            let displaced = std::mem::replace(existing, fact);
            discard_resolved_effect_iteratively(displaced);
            return Ok(());
        }
        let position = self.effects.len();
        self.effect_positions.insert(fact.id, position);
        self.effects.push(fact);
        Ok(())
    }

    /// Looks up one selected public implementation by semantic identity.
    #[must_use]
    pub fn implementation(&self, id: ImplId) -> Option<&CheckedImplementationFact> {
        Some(
            &self
                .implementations
                .get(*self.implementation_positions.get(&id)?)?
                .fact,
        )
    }

    pub(crate) fn implementation_import(&self, id: ImplId) -> Option<&ImportedImplementationFact> {
        self.implementations
            .get(*self.implementation_positions.get(&id)?)
    }

    pub(crate) fn globals(&self) -> impl Iterator<Item = &ImportedGlobalScheme> {
        self.global_order
            .iter()
            .filter_map(|identity| self.globals.get(identity))
    }

    pub(crate) fn interface_imports(&self) -> impl Iterator<Item = &ImportedInterfaceFact> {
        self.interfaces.iter()
    }

    pub(crate) fn nominals(&self) -> impl Iterator<Item = &ImportedNominalFact> {
        self.nominal_order
            .iter()
            .filter_map(|identity| self.nominals.get(identity))
    }

    pub(crate) fn has_implementation_for(&self, interface: InterfaceId) -> bool {
        self.implemented_interfaces.contains(&interface)
    }

    pub(crate) fn retain_implemented_interface(
        &mut self,
        interface: InterfaceId,
        work: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        work.charge(1)
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        self.implemented_interfaces
            .try_reserve(1)
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        self.implemented_interfaces.insert(interface);
        Ok(())
    }

    pub(crate) fn implementations(&self) -> impl Iterator<Item = &ImportedImplementationFact> {
        self.implementations.iter()
    }

    pub(crate) fn authenticate_implementation_publications(
        &self,
        type_work: &mut TypeWorkBudget,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        type_work
            .charge(self.implementations.len())
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        for imported in &self.implementations {
            authenticate_implementation_publication(
                &imported.fact,
                imported.publication.as_ref(),
                type_work,
                constraint_work,
            )?;
        }
        Ok(())
    }

    pub(crate) fn insert_global(
        &mut self,
        fact: ImportedGlobalScheme,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ()> {
        if budget.charge(1).is_err() || fact.publication.is_none() {
            discard_imported_global(fact);
            return Err(());
        }
        if !self.globals.contains_key(&fact.binder) {
            if budget.charge(1).is_err()
                || self.global_order.try_reserve(1).is_err()
                || self.globals.try_reserve(1).is_err()
            {
                discard_imported_global(fact);
                return Err(());
            }
            self.global_order.push(fact.binder);
        }
        if let Some(displaced) = self.globals.insert(fact.binder, fact) {
            discard_imported_global(displaced);
        }
        Ok(())
    }

    pub(crate) fn prepare_nominal_merge(
        &mut self,
        candidate: ImportedNominalFactRef<'_>,
        type_work: &mut TypeWorkBudget,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<PreparedImportedNominalMerge, ImportedNominalMergeFailure> {
        let validated = self.validate_nominal_merge(candidate, constraint_work)?;
        let prepared = self.materialize_nominal_merge(validated, type_work)?;
        self.reserve_prepared_nominal_merges(std::slice::from_ref(&prepared))?;
        Ok(prepared)
    }

    pub(crate) fn validate_nominal_merge<'candidate>(
        &self,
        candidate: ImportedNominalFactRef<'candidate>,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<ValidatedImportedNominalMerge<'candidate>, ImportedNominalMergeFailure> {
        let validated = self.validate_nominal_merge_shape(candidate, constraint_work)?;
        self.validate_nominal_merge_metadata(&validated, constraint_work)?;
        Ok(validated)
    }

    pub(crate) fn validate_nominal_merge_shape<'candidate>(
        &self,
        candidate: ImportedNominalFactRef<'candidate>,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<ValidatedImportedNominalMerge<'candidate>, ImportedNominalMergeFailure> {
        let family_work = candidate
            .constructors
            .len()
            .checked_add(1)
            .ok_or(ImportedNominalMergeFailure::ConstraintResource)?;
        constraint_work
            .charge(family_work)
            .map_err(|()| ImportedNominalMergeFailure::ConstraintResource)?;
        if candidate.constructor_count == 0 {
            let owner = self
                .source_owners
                .get(&candidate.id)
                .ok_or(ImportedNominalMergeFailure::Conflict)?;
            if candidate.declaration_kind != ResolvedNominalDeclarationKind::Data
                || candidate.access == ImportedTypeAccess::Transparent
                || candidate.representation.is_some()
                || candidate.representation_provenance.is_some()
                || !same_summary_resolved_type_variables_with_constraint_budget(
                    candidate.parameters,
                    owner.parameters(),
                    constraint_work,
                )
                .map_err(|failure| match failure {
                    ResolvedBuildFailure::ConstraintResource => {
                        ImportedNominalMergeFailure::ConstraintResource
                    }
                    ResolvedBuildFailure::Kind(context) => {
                        ImportedNominalMergeFailure::Kind(context)
                    }
                    _ => ImportedNominalMergeFailure::Conflict,
                })?
                || !same_origin_with_constraint_budget(
                    candidate.origin,
                    owner.origin(),
                    constraint_work,
                )
                .map_err(|failure| match failure {
                    ResolvedBuildFailure::ConstraintResource => {
                        ImportedNominalMergeFailure::ConstraintResource
                    }
                    ResolvedBuildFailure::Kind(context) => {
                        ImportedNominalMergeFailure::Kind(context)
                    }
                    _ => ImportedNominalMergeFailure::Conflict,
                })?
            {
                return Err(ImportedNominalMergeFailure::Conflict);
            }
        }
        if candidate.parameter_count != candidate.parameters.len()
            || match candidate.access {
                ImportedTypeAccess::Transparent => {
                    candidate.constructors.len() != candidate.constructor_count
                }
                ImportedTypeAccess::Opaque | ImportedTypeAccess::Hidden => {
                    !candidate.constructors.is_empty()
                }
            }
        {
            return Err(ImportedNominalMergeFailure::Conflict);
        }
        let existing = self.nominals.get(&candidate.id);
        for (ordinal, constructor) in candidate.constructors.iter().enumerate() {
            if constructor.owner() != candidate.id
                || usize::try_from(constructor.constructor()) != Ok(ordinal)
                || existing.is_some_and(|existing| {
                    !existing.constructors.is_empty()
                        && existing.constructors.get(ordinal) != Some(constructor)
                })
            {
                return Err(ImportedNominalMergeFailure::Conflict);
            }
        }
        let Some(existing) = existing else {
            return Ok(ValidatedImportedNominalMerge {
                candidate,
                action: ValidatedImportedNominalAction::Insert,
            });
        };
        if existing.parameter_count != candidate.parameter_count
            || existing.constructor_count != candidate.constructor_count
            || existing.declaration_kind != candidate.declaration_kind
            || existing.parameters.len() != candidate.parameters.len()
            || existing.display_is_private != candidate.display_is_private
        {
            return Err(ImportedNominalMergeFailure::Conflict);
        }
        let promotes_access = candidate.access.rank() > existing.access.rank();
        let fills_display = existing.display_spelling.is_none()
            && candidate.display_spelling.is_some()
            && !promotes_access;
        Ok(ValidatedImportedNominalMerge {
            candidate,
            action: if promotes_access || fills_display {
                ValidatedImportedNominalAction::Update { promotes_access }
            } else {
                ValidatedImportedNominalAction::Noop
            },
        })
    }

    pub(crate) fn validate_nominal_merge_metadata(
        &self,
        validated: &ValidatedImportedNominalMerge<'_>,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<(), ImportedNominalMergeFailure> {
        if matches!(validated.action, ValidatedImportedNominalAction::Insert) {
            return Ok(());
        }
        let candidate = validated.candidate;
        let existing = self
            .canonical_nominal_fact(candidate.id)
            .ok_or(ImportedNominalMergeFailure::Conflict)?;
        let parameters_match = same_summary_resolved_type_variables_with_constraint_budget(
            existing.parameters,
            candidate.parameters,
            constraint_work,
        )
        .map_err(|failure| match failure {
            ResolvedBuildFailure::ConstraintResource => {
                ImportedNominalMergeFailure::ConstraintResource
            }
            ResolvedBuildFailure::TypeResource | ResolvedBuildFailure::InvalidState => {
                ImportedNominalMergeFailure::Conflict
            }
            ResolvedBuildFailure::Kind(context) => ImportedNominalMergeFailure::Kind(context),
        })?;
        if !parameters_match {
            return Err(ImportedNominalMergeFailure::Conflict);
        }
        let representations_match = match (existing.representation, candidate.representation) {
            (None, None) => true,
            (Some(existing), Some(candidate)) => {
                same_type_with_constraint_budget(existing, candidate, constraint_work)
                    .map_err(|_| ImportedNominalMergeFailure::ConstraintResource)?
            }
            (None, Some(_)) | (Some(_), None) => false,
        };
        let representation_provenance_matches = match (
            existing.representation_provenance,
            candidate.representation_provenance,
        ) {
            (None, None) => true,
            (Some(existing), Some(candidate)) => {
                same_resolved_type_provenance_with_constraint_budget(
                    existing,
                    candidate,
                    constraint_work,
                )
                .map_err(|_| ImportedNominalMergeFailure::ConstraintResource)?
            }
            (None, Some(_)) | (Some(_), None) => false,
        };
        let origins_match =
            same_origin_with_constraint_budget(existing.origin, candidate.origin, constraint_work)
                .map_err(|failure| match failure {
                    ResolvedBuildFailure::ConstraintResource => {
                        ImportedNominalMergeFailure::ConstraintResource
                    }
                    ResolvedBuildFailure::TypeResource | ResolvedBuildFailure::InvalidState => {
                        ImportedNominalMergeFailure::Conflict
                    }
                    ResolvedBuildFailure::Kind(context) => {
                        ImportedNominalMergeFailure::Kind(context)
                    }
                })?;
        let defining_display_conflict =
            existing.display_is_private && existing.display_spelling != candidate.display_spelling;
        if !representations_match
            || !representation_provenance_matches
            || !origins_match
            || defining_display_conflict
        {
            return Err(ImportedNominalMergeFailure::Conflict);
        }
        Ok(())
    }

    pub(crate) fn materialize_nominal_merge(
        &mut self,
        validated: ValidatedImportedNominalMerge<'_>,
        type_work: &mut TypeWorkBudget,
    ) -> Result<PreparedImportedNominalMerge, ImportedNominalMergeFailure> {
        let candidate = validated.candidate;
        match validated.action {
            ValidatedImportedNominalAction::Insert => {
                let family_work = candidate
                    .constructors
                    .len()
                    .checked_add(1)
                    .ok_or(ImportedNominalMergeFailure::TypeResource)?;
                let retention_work = candidate.parameters.iter().try_fold(
                    family_work
                        .checked_add(1)
                        .ok_or(ImportedNominalMergeFailure::TypeResource)?,
                    |work, parameter| {
                        work.checked_add(
                            retained_type_variable_work(parameter)
                                .map_err(|_| ImportedNominalMergeFailure::TypeResource)?,
                        )
                        .ok_or(ImportedNominalMergeFailure::TypeResource)
                    },
                )?;
                type_work
                    .charge(retention_work)
                    .map_err(|()| ImportedNominalMergeFailure::TypeResource)?;
                let mut constructors = Vec::new();
                constructors
                    .try_reserve_exact(candidate.constructors.len())
                    .map_err(|_| ImportedNominalMergeFailure::TypeResource)?;
                constructors.extend_from_slice(candidate.constructors);
                let mut parameters = ResolvedTypeVariableBuffer(Vec::new());
                parameters
                    .try_reserve(candidate.parameters.len())
                    .map_err(|_| ImportedNominalMergeFailure::TypeResource)?;
                for parameter in candidate.parameters {
                    parameters.push(
                        clone_type_variable_after_combined_precharge(parameter)
                            .map_err(|_| ImportedNominalMergeFailure::TypeResource)?,
                    );
                }
                let display_spelling = candidate
                    .display_spelling
                    .map(try_clone_string)
                    .transpose()
                    .map_err(|_| ImportedNominalMergeFailure::TypeResource)?;
                // Canonical metadata authenticates the merge, but an opaque
                // source projection retains it only in the linkage sidecar.
                let source_candidate = ImportedNominalFactRef {
                    representation: candidate
                        .representation
                        .filter(|_| candidate.access != ImportedTypeAccess::Opaque),
                    representation_provenance: candidate
                        .representation_provenance
                        .filter(|_| candidate.access != ImportedTypeAccess::Opaque),
                    ..candidate
                };
                let representation = source_candidate
                    .representation
                    .map(|representation| clone_type_with_budget(representation, type_work))
                    .transpose()
                    .map_err(|()| ImportedNominalMergeFailure::TypeResource)?;
                let representation_provenance = source_candidate.representation_provenance.cloned();
                Ok(PreparedImportedNominalMerge {
                    action: Some(PreparedImportedNominalAction::Insert(ImportedNominalFact {
                        representation_provenance,
                        id: candidate.id,
                        declaration_kind: candidate.declaration_kind,
                        parameter_count: candidate.parameter_count,
                        constructor_count: candidate.constructor_count,
                        parameters: parameters.into_boxed_slice(),
                        representation,
                        constructors: constructors.into_boxed_slice(),
                        access: candidate.access,
                        display_spelling,
                        display_is_private: candidate.display_is_private,
                        origin: candidate.origin.clone(),
                    })),
                })
            }
            ValidatedImportedNominalAction::Noop => Ok(PreparedImportedNominalMerge {
                action: Some(PreparedImportedNominalAction::Noop),
            }),
            ValidatedImportedNominalAction::Update { promotes_access } => {
                let retained_family = if promotes_access {
                    candidate.constructors
                } else {
                    &[]
                };
                type_work
                    .charge(retained_family.len())
                    .map_err(|()| ImportedNominalMergeFailure::TypeResource)?;
                let mut constructors = Vec::new();
                constructors
                    .try_reserve_exact(retained_family.len())
                    .map_err(|_| ImportedNominalMergeFailure::TypeResource)?;
                constructors.extend_from_slice(retained_family);
                Ok(PreparedImportedNominalMerge {
                    action: Some(PreparedImportedNominalAction::Update {
                        id: candidate.id,
                        access: promotes_access.then_some(candidate.access),
                        constructors: (promotes_access && !candidate.constructors.is_empty())
                            .then(|| constructors.into_boxed_slice()),
                        display_spelling: candidate
                            .display_spelling
                            .map(try_clone_string)
                            .transpose()
                            .map_err(|_| ImportedNominalMergeFailure::TypeResource)?,
                    }),
                })
            }
        }
    }

    pub(crate) fn materialize_nominal_merge_after_precharge(
        &mut self,
        validated: ValidatedImportedNominalMerge<'_>,
    ) -> Result<PreparedImportedNominalMerge, ImportedNominalMergeFailure> {
        self.materialize_nominal_merge(validated, &mut TypeWorkBudget::unbounded())
    }

    pub(crate) fn reserve_prepared_nominal_merges(
        &mut self,
        prepared: &[PreparedImportedNominalMerge],
    ) -> Result<(), ImportedNominalMergeFailure> {
        let insert_count = prepared.iter().try_fold(0_usize, |count, prepared| {
            count
                .checked_add(usize::from(matches!(
                    &prepared.action,
                    Some(PreparedImportedNominalAction::Insert(_))
                )))
                .ok_or(ImportedNominalMergeFailure::TypeResource)
        })?;
        self.nominal_order
            .try_reserve(insert_count)
            .map_err(|_| ImportedNominalMergeFailure::TypeResource)?;
        self.nominals
            .try_reserve(insert_count)
            .map_err(|_| ImportedNominalMergeFailure::TypeResource)
    }

    pub(crate) fn commit_nominal_merge(
        &mut self,
        mut prepared: PreparedImportedNominalMerge,
    ) -> Result<(), ImportedNominalMergeFailure> {
        let action = prepared
            .action
            .take()
            .ok_or(ImportedNominalMergeFailure::Conflict)?;
        match action {
            PreparedImportedNominalAction::Noop => Ok(()),
            PreparedImportedNominalAction::Insert(fact) => {
                if self.nominals.contains_key(&fact.id) {
                    discard_imported_nominal(fact);
                    return Err(ImportedNominalMergeFailure::Conflict);
                }
                self.nominal_order.push(fact.id);
                if let Some(displaced) = self.nominals.insert(fact.id, fact) {
                    discard_imported_nominal(displaced);
                    return Err(ImportedNominalMergeFailure::Conflict);
                }
                Ok(())
            }
            PreparedImportedNominalAction::Update {
                id,
                access,
                constructors,
                display_spelling,
            } => {
                let existing = self
                    .nominals
                    .get_mut(&id)
                    .ok_or(ImportedNominalMergeFailure::Conflict)?;
                if let Some(access) = access {
                    existing.access = access;
                    if access == ImportedTypeAccess::Opaque {
                        if let Some(representation) = existing.representation.take() {
                            discard_type_iteratively(representation);
                        }
                        existing.representation_provenance = None;
                    }
                }
                if let Some(constructors) = constructors {
                    existing.constructors = constructors;
                }
                if display_spelling.is_some() {
                    existing.display_spelling = display_spelling;
                }
                Ok(())
            }
        }
    }

    pub(crate) fn commit_prepared_nominal_merges(
        &mut self,
        prepared: &mut Vec<PreparedImportedNominalMerge>,
    ) {
        for mut prepared in prepared.drain(..) {
            let action = prepared
                .action
                .take()
                .expect("a validated nominal action remains staged until commit");
            match action {
                PreparedImportedNominalAction::Noop => {}
                PreparedImportedNominalAction::Insert(fact) => {
                    debug_assert!(!self.nominals.contains_key(&fact.id));
                    self.nominal_order.push(fact.id);
                    let displaced = self.nominals.insert(fact.id, fact);
                    debug_assert!(displaced.is_none());
                    if let Some(displaced) = displaced {
                        discard_imported_nominal(displaced);
                    }
                }
                PreparedImportedNominalAction::Update {
                    id,
                    access,
                    constructors,
                    display_spelling,
                } => {
                    let existing = self
                        .nominals
                        .get_mut(&id)
                        .expect("a validated nominal update retains its destination");
                    if let Some(access) = access {
                        existing.access = access;
                        if access == ImportedTypeAccess::Opaque {
                            if let Some(representation) = existing.representation.take() {
                                discard_type_iteratively(representation);
                            }
                            existing.representation_provenance = None;
                        }
                    }
                    if let Some(constructors) = constructors {
                        existing.constructors = constructors;
                    }
                    if display_spelling.is_some() {
                        existing.display_spelling = display_spelling;
                    }
                }
            }
        }
    }

    pub(crate) fn reserve_constructor_inserts(&mut self, count: usize) -> Result<(), ()> {
        self.constructors.try_reserve(count).map_err(|_| ())
    }

    pub(crate) fn commit_constructor_inserts(
        &mut self,
        constructors: impl IntoIterator<Item = ImportedConstructorFact>,
    ) {
        for constructor in constructors {
            debug_assert!(!self.constructors.contains_key(&constructor.id));
            let displaced = self.constructors.insert(constructor.id, constructor);
            debug_assert!(displaced.is_none());
            if let Some(displaced) = displaced {
                displaced.discard_iteratively();
            }
        }
    }

    #[cfg(test)]
    pub(crate) fn merge_nominal(
        &mut self,
        fact: ImportedNominalFact,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ImportedNominalMergeFailure> {
        let mut constraint_work =
            crate::interface::InterfaceConstraintBudget::with_limit(usize::MAX);
        let prepared = self.prepare_nominal_merge(
            ImportedNominalFactRef {
                id: fact.id,
                declaration_kind: fact.declaration_kind,
                parameter_count: fact.parameter_count,
                constructor_count: fact.constructor_count,
                parameters: &fact.parameters,
                representation: fact.representation.as_ref(),
                representation_provenance: fact.representation_provenance.as_ref(),
                constructors: &fact.constructors,
                access: fact.access,
                display_spelling: fact.display_spelling.as_deref(),
                display_is_private: fact.display_is_private,
                origin: &fact.origin,
            },
            budget,
            &mut constraint_work,
        );
        discard_imported_nominal(fact);
        self.commit_nominal_merge(prepared?)
    }

    #[cfg(test)]
    pub(crate) fn insert_constructor(
        &mut self,
        fact: ImportedConstructorFact,
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ()> {
        if !self.constructors.contains_key(&fact.id)
            && (budget.charge(1).is_err() || self.constructors.try_reserve(1).is_err())
        {
            fact.discard_iteratively();
            return Err(());
        }
        if let Some(displaced) = self.constructors.insert(fact.id, fact) {
            displaced.discard_iteratively();
        }
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn insert_interface(
        &mut self,
        fact: CheckedInterfaceFact,
        direct_dependency: ModuleId,
        available_at: Span,
        publicly_available: bool,
    ) {
        let authority_method_indices = fact
            .methods
            .iter()
            .enumerate()
            .filter_map(|(index, method)| {
                (!method.authoritative_type_parameters().is_empty()).then_some(index)
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        self.insert_interface_with_authority_indices(
            fact,
            authority_method_indices,
            direct_dependency,
            available_at,
            publicly_available,
        );
    }

    pub(crate) fn insert_interface_with_authority_indices(
        &mut self,
        fact: impl Into<SharedCheckedInterfaceFact>,
        authority_method_indices: Box<[usize]>,
        direct_dependency: ModuleId,
        available_at: Span,
        publicly_available: bool,
    ) {
        let fact = fact.into();
        let position = self.interfaces.len();
        self.interface_positions.insert(fact.id, position);
        self.interfaces.push(ImportedInterfaceFact {
            fact,
            authority_method_indices,
            direct_dependency,
            available_at,
            publicly_available,
        });
    }

    pub(crate) fn merge_interface_route(
        &mut self,
        id: InterfaceId,
        direct_dependency: ModuleId,
        available_at: Span,
        publicly_available: bool,
    ) {
        let Some(imported) = self
            .interface_positions
            .get(&id)
            .and_then(|position| self.interfaces.get_mut(*position))
        else {
            return;
        };
        if !publicly_available || imported.publicly_available {
            return;
        }
        imported.direct_dependency = direct_dependency;
        imported.available_at = available_at;
        imported.publicly_available = true;
    }

    pub(crate) fn reserve_interface(&mut self) -> Result<(), ()> {
        self.interfaces.try_reserve(1).map_err(|_| ())?;
        self.interface_positions.try_reserve(1).map_err(|_| ())
    }

    #[cfg(test)]
    pub(crate) fn insert_implementation(
        &mut self,
        fact: CheckedImplementationFact,
        authorization: ImplementationAuthorization,
        public_authorization: Option<ImplementationAuthorization>,
    ) {
        let publication = implementation_publication_for_test(&fact);
        self.insert_implementation_with_publication(
            fact,
            publication,
            authorization,
            public_authorization,
        );
    }

    pub(crate) fn insert_implementation_with_publication(
        &mut self,
        fact: CheckedImplementationFact,
        publication: Arc<CheckedImplementationFact>,
        authorization: ImplementationAuthorization,
        public_authorization: Option<ImplementationAuthorization>,
    ) {
        let position = self.implementations.len();
        self.implementation_positions.insert(fact.id, position);
        self.implementations.push(ImportedImplementationFact {
            publication: Some(publication),
            fact,
            authorization,
            public_authorization,
        });
    }

    pub(crate) fn reserve_implementation(&mut self) -> Result<(), ()> {
        self.implementations.try_reserve(1).map_err(|_| ())?;
        self.implementation_positions.try_reserve(1).map_err(|_| ())
    }

    pub(crate) fn reserve_public_implementation(&mut self) -> Result<(), ()> {
        self.public_implementation_order
            .try_reserve(1)
            .map_err(|_| ())
    }

    pub(crate) fn mark_implementation_public(&mut self, id: ImplId) -> Result<(), ()> {
        if !self.implementation_positions.contains_key(&id) {
            return Err(());
        }
        self.public_implementation_order.push(id);
        Ok(())
    }

    pub(crate) fn commit_existing_implementation_routes(
        &mut self,
        id: ImplId,
        authorization: Option<ImplementationAuthorization>,
        public_authorization: Option<ImplementationAuthorization>,
        mark_public: bool,
    ) -> Result<(), ()> {
        let position = *self.implementation_positions.get(&id).ok_or(())?;
        let imported = self.implementations.get_mut(position).ok_or(())?;
        if let Some(authorization) = authorization {
            imported.authorization = authorization;
        }
        if let Some(public_authorization) = public_authorization {
            imported.public_authorization = Some(public_authorization);
        }
        if mark_public {
            self.public_implementation_order.push(id);
        }
        Ok(())
    }

    pub(crate) fn public_implementation_ids(&self) -> &[ImplId] {
        &self.public_implementation_order
    }
}

fn imported_nominal_family_is_valid(fact: &ImportedNominalFact) -> bool {
    if fact.constructor_count == 0
        || matches!(fact.declaration_kind, ResolvedNominalDeclarationKind::Data)
            && fact.representation.is_some()
        || matches!(
            fact.declaration_kind,
            ResolvedNominalDeclarationKind::Newtype
        ) && (fact.constructor_count != 1
            || fact.access == ImportedTypeAccess::Transparent && fact.representation.is_none())
    {
        return false;
    }
    match fact.access {
        ImportedTypeAccess::Transparent => {
            fact.constructors.len() == fact.constructor_count
                && fact
                    .constructors
                    .iter()
                    .enumerate()
                    .all(|(index, constructor)| {
                        constructor.owner() == fact.id
                            && usize::try_from(constructor.constructor()) == Ok(index)
                    })
        }
        ImportedTypeAccess::Opaque | ImportedTypeAccess::Hidden => fact.constructors.is_empty(),
    }
}

impl Drop for ImportedFacts {
    fn drop(&mut self) {
        for (_, fact) in self.globals.drain() {
            drop(fact.scheme);
            discard_origin_iteratively(fact.origin);
        }
        self.global_order.clear();
        for (_, fact) in self.nominals.drain() {
            for parameter in fact.parameters.into_vec() {
                discard_origin_iteratively(parameter.origin);
            }
            if let Some(representation) = fact.representation {
                discard_type_iteratively(representation);
            }
            discard_origin_iteratively(fact.origin);
        }
        self.nominal_order.clear();
        for (_, representation) in self.canonical_representations.drain() {
            discard_canonical_representation_fact(representation);
        }
        for (_, fact) in self.constructors.drain() {
            drop(fact.scheme);
            if let Some(payload) = fact.payload {
                discard_type_iteratively(payload);
            }
            discard_origin_iteratively(fact.origin);
        }
        for imported in self.interfaces.drain(..) {
            drop(imported.fact);
        }
        self.interface_positions.clear();
        for effect in self.effects.drain(..) {
            discard_resolved_effect_iteratively(effect);
        }
        self.effect_positions.clear();
        for imported in self.implementations.drain(..) {
            drop(imported.fact);
        }
        self.implementation_positions.clear();
        self.public_implementation_order.clear();
    }
}

fn discard_imported_global(fact: ImportedGlobalScheme) {
    let ImportedGlobalScheme { scheme, origin, .. } = fact;
    drop(scheme);
    discard_origin_iteratively(origin);
}

fn discard_imported_nominal(fact: ImportedNominalFact) {
    for parameter in fact.parameters.into_vec() {
        discard_origin_iteratively(parameter.origin);
    }
    if let Some(representation) = fact.representation {
        discard_type_iteratively(representation);
    }
    discard_origin_iteratively(fact.origin);
}

/// Immutable defining owner parameters shared without duplicating their kinds or provenance.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SharedOwnerParameters(Option<Arc<OwnerParameterRecords>>);

#[derive(Debug, Eq, PartialEq)]
struct OwnerParameterRecords {
    parameters: Box<[ResolvedTypeVariable]>,
}

impl Drop for OwnerParameterRecords {
    fn drop(&mut self) {
        for parameter in std::mem::take(&mut self.parameters).into_vec() {
            discard_resolved_type_variable(parameter);
        }
    }
}

impl SharedOwnerParameters {
    pub(crate) fn from_boxed_with_budget(
        parameters: Box<[ResolvedTypeVariable]>,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        let records = OwnerParameterRecords { parameters };
        budget
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        Ok(Self(Some(Arc::new(records))))
    }

    pub(crate) fn clone_with_budget(
        &self,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        if self.0.is_none() {
            return Ok(Self::default());
        }
        budget
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        Ok(self.clone())
    }

    #[cfg(test)]
    pub(crate) fn from_boxed_for_test(parameters: Box<[ResolvedTypeVariable]>) -> Self {
        Self::from_boxed_with_budget(parameters, &mut TypeWorkBudget::unbounded())
            .expect("an in-memory shared owner fixture fits its work bound")
    }
    #[cfg(test)]
    fn into_vec(self) -> Vec<ResolvedTypeVariable> {
        match self.0 {
            None => Vec::new(),
            Some(records) => match Arc::try_unwrap(records) {
                Ok(mut records) => std::mem::take(&mut records.parameters).into_vec(),
                Err(records) => {
                    let mut parameters = ResolvedTypeVariableBuffer(Vec::new());
                    parameters
                        .try_reserve(records.parameters.len())
                        .expect("fixture parameter storage");
                    for parameter in records.parameters.iter() {
                        parameters.push(
                            clone_resolved_type_variable_with_budget(
                                parameter,
                                &mut TypeWorkBudget::unbounded(),
                            )
                            .expect("fixture parameter copy"),
                        );
                    }
                    parameters.into_vec()
                }
            },
        }
    }

    #[cfg(test)]
    pub(crate) fn make_mut_for_test(&mut self) -> &mut [ResolvedTypeVariable] {
        if self.0.as_mut().and_then(Arc::get_mut).is_none() {
            let mut parameters = ResolvedTypeVariableBuffer(Vec::new());
            parameters
                .try_reserve(self.len())
                .expect("fixture parameter storage");
            for parameter in self.iter() {
                parameters.push(
                    clone_resolved_type_variable_with_budget(
                        parameter,
                        &mut TypeWorkBudget::unbounded(),
                    )
                    .expect("fixture parameter copy"),
                );
            }
            *self = Self::from_boxed_for_test(parameters.into_vec().into_boxed_slice());
        }
        self.0
            .as_mut()
            .and_then(Arc::get_mut)
            .expect("a detached fixture owns its parameters")
            .parameters
            .as_mut()
    }
}

#[cfg(test)]
impl From<Box<[ResolvedTypeVariable]>> for SharedOwnerParameters {
    fn from(parameters: Box<[ResolvedTypeVariable]>) -> Self {
        Self::from_boxed_for_test(parameters)
    }
}
#[cfg(test)]
impl<const N: usize> From<Box<[ResolvedTypeVariable; N]>> for SharedOwnerParameters {
    fn from(parameters: Box<[ResolvedTypeVariable; N]>) -> Self {
        Self::from_boxed_for_test(parameters)
    }
}

impl std::ops::Deref for SharedOwnerParameters {
    type Target = [ResolvedTypeVariable];
    fn deref(&self) -> &Self::Target {
        self.0
            .as_ref()
            .map_or(&[], |records| records.parameters.as_ref())
    }
}
impl AsRef<[ResolvedTypeVariable]> for SharedOwnerParameters {
    fn as_ref(&self) -> &[ResolvedTypeVariable] {
        self
    }
}
impl<'parameters> IntoIterator for &'parameters SharedOwnerParameters {
    type Item = &'parameters ResolvedTypeVariable;
    type IntoIter = std::slice::Iter<'parameters, ResolvedTypeVariable>;
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

// A canonical binder either owns its record or borrows one validated slot
// from immutable defining records. The guard owns iterative disposal on every
// failed publication and registry teardown path.
#[derive(Debug)]
struct CanonicalTypeVariable(Option<CanonicalTypeVariableValue>);
#[derive(Debug, Eq, PartialEq)]
enum CanonicalTypeVariableValue {
    Owned(ResolvedTypeVariable),
    SharedOriginal {
        parameters: SharedOwnerParameters,
        slot: usize,
    },
}
impl CanonicalTypeVariable {
    fn shared_original(
        parameters: &SharedOwnerParameters,
        slot: usize,
        identity: TypeVariableId,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        if parameters.get(slot).map(|parameter| parameter.id) != Some(identity) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        Ok(Self(Some(CanonicalTypeVariableValue::SharedOriginal {
            parameters: parameters.clone_with_budget(budget)?,
            slot,
        })))
    }
    fn clone_shared_with_budget(
        &self,
        budget: &mut TypeWorkBudget,
    ) -> Result<Option<Self>, ResolvedBuildFailure> {
        match self.0.as_ref() {
            Some(CanonicalTypeVariableValue::SharedOriginal { parameters, slot }) => {
                Self::shared_original(parameters, *slot, self.id, budget).map(Some)
            }
            _ => Ok(None),
        }
    }
}
impl Clone for CanonicalTypeVariable {
    fn clone(&self) -> Self {
        match self
            .0
            .as_ref()
            .expect("a canonical binder retains its record")
        {
            CanonicalTypeVariableValue::Owned(parameter) => {
                clone_resolved_type_variable_with_budget(
                    parameter,
                    &mut TypeWorkBudget::unbounded(),
                )
                .expect("a canonical binder compatibility clone retains its complete record")
                .into()
            }
            CanonicalTypeVariableValue::SharedOriginal { parameters, slot } => {
                Self(Some(CanonicalTypeVariableValue::SharedOriginal {
                    parameters: parameters.clone(),
                    slot: *slot,
                }))
            }
        }
    }
}

impl PartialEq for CanonicalTypeVariable {
    fn eq(&self, other: &Self) -> bool {
        self.as_ref() == other.as_ref()
    }
}
impl Eq for CanonicalTypeVariable {}

impl From<ResolvedTypeVariable> for CanonicalTypeVariable {
    fn from(parameter: ResolvedTypeVariable) -> Self {
        Self(Some(CanonicalTypeVariableValue::Owned(parameter)))
    }
}
impl std::ops::Deref for CanonicalTypeVariable {
    type Target = ResolvedTypeVariable;
    fn deref(&self) -> &ResolvedTypeVariable {
        match self
            .0
            .as_ref()
            .expect("a canonical binder retains its record")
        {
            CanonicalTypeVariableValue::Owned(parameter) => parameter,
            CanonicalTypeVariableValue::SharedOriginal { parameters, slot } => &parameters[*slot], // The sole constructor validates an immutable slot.
        }
    }
}
impl AsRef<ResolvedTypeVariable> for CanonicalTypeVariable {
    fn as_ref(&self) -> &ResolvedTypeVariable {
        self
    }
}
#[cfg(test)]
impl std::ops::DerefMut for CanonicalTypeVariable {
    fn deref_mut(&mut self) -> &mut ResolvedTypeVariable {
        if matches!(
            self.0.as_ref(),
            Some(CanonicalTypeVariableValue::SharedOriginal { .. })
        ) {
            let parameter =
                clone_resolved_type_variable_with_budget(self, &mut TypeWorkBudget::unbounded())
                    .expect("an immutable canonical fixture binder can detach");
            self.0 = Some(CanonicalTypeVariableValue::Owned(parameter));
        }
        match self.0.as_mut().expect("fixture canonical binder record") {
            CanonicalTypeVariableValue::Owned(parameter) => parameter,
            CanonicalTypeVariableValue::SharedOriginal { .. } => {
                unreachable!("fixture detached above")
            }
        }
    }
}
impl Drop for CanonicalTypeVariable {
    fn drop(&mut self) {
        if let Some(CanonicalTypeVariableValue::Owned(parameter)) = self.0.take() {
            discard_resolved_type_variable(parameter);
        }
    }
}

/// One immutable admitted interface fact shared across checked, export, and
/// import views. Availability routes remain separate from defining authority.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SharedCheckedInterfaceFact(Arc<CheckedInterfaceFact>);

impl SharedCheckedInterfaceFact {
    pub(crate) fn from_owned_with_budget(
        fact: CheckedInterfaceFact,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        // The fact already owns iterative disposal before any fallible charge.
        budget
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        Ok(Self(Arc::new(fact)))
    }

    pub(crate) fn clone_with_budget(
        &self,
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        budget
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        Ok(self.clone())
    }
}
impl std::ops::Deref for SharedCheckedInterfaceFact {
    type Target = CheckedInterfaceFact;
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}
impl AsRef<CheckedInterfaceFact> for SharedCheckedInterfaceFact {
    fn as_ref(&self) -> &CheckedInterfaceFact {
        self
    }
}
#[cfg(test)]
impl From<CheckedInterfaceFact> for SharedCheckedInterfaceFact {
    fn from(fact: CheckedInterfaceFact) -> Self {
        Self(Arc::new(fact))
    }
}
#[cfg(test)]
impl std::ops::DerefMut for SharedCheckedInterfaceFact {
    fn deref_mut(&mut self) -> &mut CheckedInterfaceFact {
        if Arc::get_mut(&mut self.0).is_none() {
            let mut types = TypeWorkBudget::unbounded();
            let mut constraints =
                crate::interface::InterfaceConstraintBudget::with_limit(usize::MAX);
            let detached = clone_checked_interface_fact(self, None, &mut types, &mut constraints)
                .expect("an admitted fixture fact can detach before tampering");
            self.0 = Arc::new(detached);
        }
        Arc::get_mut(&mut self.0).expect("fixture fact detachment is exclusive")
    }
}

/// One body-free checked interface fact keyed by stable semantic identity.
#[derive(Debug, Eq, PartialEq)]
pub struct CheckedInterfaceFact {
    /// Stable defining interface identity.
    pub id: InterfaceId,
    /// Exact defining source spelling.
    pub spelling: String,
    /// Ordered interface parameters with their defining identities.
    pub parameters: SharedOwnerParameters,
    /// Optional total determinant key in interface declaration coordinates.
    determination: Option<DeterminationKey>,
    /// Checked methods in semantic declaration order.
    pub methods: Box<[CheckedInterfaceMethodFact]>,
    /// Causal declaration provenance.
    pub origin: Origin,
    /// Complete declaration span.
    pub span: Span,
}

#[derive(Debug, Eq, PartialEq)]
pub(crate) struct ImportedInterfaceFact {
    pub(crate) fact: SharedCheckedInterfaceFact,
    // Only polymorphic methods have entries. Monomorphic checker views can
    // therefore skip authority discovery without another all-method pass.
    authority_method_indices: Box<[usize]>,
    pub(crate) direct_dependency: ModuleId,
    pub(crate) available_at: Span,
    pub(crate) publicly_available: bool,
}

impl ImportedInterfaceFact {
    pub(crate) fn authority_methods(&self) -> impl Iterator<Item = &CheckedInterfaceMethodFact> {
        self.authority_method_indices
            .iter()
            .filter_map(|index| self.fact.methods.get(*index))
    }
}

impl CheckedInterfaceFact {
    pub(crate) fn new(
        id: InterfaceId,
        spelling: String,
        parameters: impl Into<SharedOwnerParameters>,
        determination: Option<DeterminationKey>,
        methods: Box<[CheckedInterfaceMethodFact]>,
        origin: Origin,
        span: Span,
    ) -> Self {
        Self {
            id,
            spelling,
            parameters: parameters.into(),
            determination,
            methods,
            origin,
            span,
        }
    }

    /// Looks up one checked method within its owning interface.
    #[must_use]
    pub fn method(&self, id: MethodId) -> Option<&CheckedInterfaceMethodFact> {
        self.methods.iter().find(|method| method.id == id)
    }

    /// Returns the determinant declaration positions when this interface has a key.
    #[must_use]
    pub(crate) fn determinant_positions(&self) -> Option<&[usize]> {
        self.determination.as_ref().map(DeterminationKey::positions)
    }

    pub(crate) const fn determination(&self) -> Option<&DeterminationKey> {
        self.determination.as_ref()
    }

    #[cfg(test)]
    pub(crate) fn without_methods_for_test(
        id: InterfaceId,
        spelling: String,
        parameters: Box<[ResolvedTypeVariable]>,
        origin: Origin,
        span: Span,
    ) -> Self {
        Self {
            id,
            spelling,
            parameters: SharedOwnerParameters::from_boxed_for_test(parameters),
            determination: None,
            methods: Box::new([]),
            origin,
            span,
        }
    }
}

impl Drop for CheckedInterfaceFact {
    fn drop(&mut self) {
        drop(std::mem::take(&mut self.parameters));
        for method in std::mem::take(&mut self.methods).into_vec() {
            drop(method);
        }
        discard_origin_iteratively(std::mem::replace(
            &mut self.origin,
            Origin::Source(self.span),
        ));
    }
}

/// One checked method signature nested under an interface fact.
#[derive(Debug, Eq, PartialEq)]
pub struct CheckedInterfaceMethodFact {
    /// Stable method identity.
    pub id: MethodId,
    /// Exact defining source spelling.
    pub spelling: String,
    /// Ordered canonical method-local type binders retained separately from the value type.
    pub(crate) type_parameters: SharedOwnerParameters,
    /// Parent slots inherited by generated registry schemes; never method-local binders.
    pub(crate) inherited_parameters: Box<[InheritedOwnerParameter]>,
    /// Source-authenticated binder payload attached structurally to this method.
    method_binder_authority: Option<SharedOwnerParameters>,
    /// Checked source value type before evidence lowering.
    pub(crate) value_type: Type,
    /// Causal method provenance.
    pub origin: Origin,
    /// Defining source annotation subspan.
    annotation_span: Span,
    /// Complete method-signature span.
    pub span: Span,
}

impl Drop for CheckedInterfaceMethodFact {
    fn drop(&mut self) {
        drop(std::mem::take(&mut self.type_parameters));
        drop(self.method_binder_authority.take());
        discard_type_iteratively(std::mem::replace(&mut self.value_type, Type::Unit));
        discard_origin_iteratively(std::mem::replace(
            &mut self.origin,
            Origin::Source(self.span),
        ));
    }
}

impl CheckedInterfaceMethodFact {
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn with_mirrored_binder_authority_for_test(
        id: MethodId,
        spelling: String,
        type_parameters: impl Into<SharedOwnerParameters>,
        value_type: Type,
        origin: Origin,
        annotation_span: Span,
        span: Span,
    ) -> Self {
        let type_parameters = type_parameters.into();
        let method_binder_authority = if type_parameters.is_empty() {
            None
        } else {
            Some(type_parameters.clone())
        };
        Self {
            inherited_parameters: Box::new([]),
            id,
            spelling,
            type_parameters,
            method_binder_authority,
            value_type,
            origin,
            annotation_span,
            span,
        }
    }

    pub(crate) fn with_resolved_binder_authority(
        source: &ResolvedInterfaceMethod,
        type_parameters: SharedOwnerParameters,
        value_type: Type,
        type_work: &mut TypeWorkBudget,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        let value_type = IterativeTypeOwner::new(value_type);
        let method_binder_authority = clone_method_binder_authority_payload(
            &source.type_parameters,
            type_work,
            constraint_work,
        )?;
        Ok(Self {
            inherited_parameters: Box::new([]),
            id: source.id,
            spelling: source.spelling.clone(),
            type_parameters,
            method_binder_authority,
            value_type: value_type.into_inner(),
            origin: source.origin.clone(),
            annotation_span: source.annotation.span,
            span: source.span,
        })
    }

    pub(crate) fn clone_with_binder_authority(
        source: &Self,
        type_parameters: Box<[ResolvedTypeVariable]>,
        value_type: Type,
        type_work: &mut TypeWorkBudget,
        constraint_work: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        let value_type = IterativeTypeOwner::new(value_type);
        let type_parameters =
            SharedOwnerParameters::from_boxed_with_budget(type_parameters, type_work)?;
        let method_binder_authority = clone_method_binder_authority_payload(
            source
                .method_binder_authority
                .as_ref()
                .unwrap_or(&source.type_parameters),
            type_work,
            constraint_work,
        )?;
        type_work
            .charge(source.inherited_parameters.len())
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        let mut inherited_parameters = Vec::new();
        inherited_parameters
            .try_reserve_exact(source.inherited_parameters.len())
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        inherited_parameters.extend(source.inherited_parameters.iter().copied());
        Ok(Self {
            inherited_parameters: inherited_parameters.into_boxed_slice(),
            id: source.id,
            spelling: source.spelling.clone(),
            type_parameters,
            method_binder_authority,
            value_type: value_type.into_inner(),
            origin: source.origin.clone(),
            annotation_span: source.annotation_span,
            span: source.span,
        })
    }

    pub(crate) fn authenticate_shared_original(
        &self,
        constraints: &mut crate::interface::InterfaceConstraintBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        authenticate_method_binder_authority(self, constraints)
    }

    pub(crate) fn with_inherited_parameters(
        mut self,
        owner: OwnerId,
        parameters: &[ResolvedTypeVariable],
        budget: &mut TypeWorkBudget,
    ) -> Result<Self, ResolvedBuildFailure> {
        let mut roles = Vec::new();
        budget
            .charge(parameters.len())
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        roles
            .try_reserve_exact(parameters.len())
            .map_err(|_| ResolvedBuildFailure::TypeResource)?;
        for (slot, parameter) in parameters.iter().enumerate() {
            roles.push(
                InheritedOwnerParameter::at_slot(owner, slot, parameter.id, budget)
                    .map_err(|()| ResolvedBuildFailure::TypeResource)?,
            );
        }
        self.inherited_parameters = roles.into_boxed_slice();
        Ok(self)
    }
    pub(crate) fn authenticate_inherited_parameters(
        &self,
        owner: OwnerId,
        parameters: &[ResolvedTypeVariable],
        budget: &mut TypeWorkBudget,
    ) -> Result<(), ResolvedBuildFailure> {
        if self.inherited_parameters.len() != parameters.len() {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        for (slot, (role, parameter)) in
            self.inherited_parameters.iter().zip(parameters).enumerate()
        {
            budget
                .charge(1)
                .map_err(|()| ResolvedBuildFailure::TypeResource)?;
            if role.owner != owner
                || usize::try_from(role.slot) != Ok(slot)
                || role.binder != parameter.id
            {
                return Err(ResolvedBuildFailure::InvalidState);
            }
        }
        Ok(())
    }

    /// Borrows the ordered canonical method-local binder records.
    #[must_use]
    pub fn type_parameters(&self) -> &[ResolvedTypeVariable] {
        &self.type_parameters
    }

    /// Borrows the private source-authenticated method-local binder payload.
    #[must_use]
    pub(crate) fn authoritative_type_parameters(&self) -> &[ResolvedTypeVariable] {
        match &self.method_binder_authority {
            Some(parameters) => parameters,
            None => &[],
        }
    }

    /// Borrows the checked source value type before evidence lowering.
    #[must_use]
    pub const fn value_type(&self) -> &Type {
        &self.value_type
    }

    /// Returns the defining source annotation subspan.
    #[must_use]
    pub(crate) const fn annotation_span(&self) -> Span {
        self.annotation_span
    }
}

