#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ResolvedBuildFailure {
    InvalidState,
    Kind(crate::kind::KindFailureContext),
    TypeResource,
    ConstraintResource,
}

impl ResolvedBuildFailure {
    pub(crate) fn is_resource_exhaustion(self) -> bool {
        matches!(self, Self::TypeResource | Self::ConstraintResource)
    }
}

fn reserve_summary_implementation_storage(
    implementations: &mut Vec<AuthorizedImplementationFact>,
    positions: &mut HashMap<ImplId, usize>,
    retained_count: usize,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    let storage_work = retained_count
        .checked_mul(2)
        .ok_or(ResolvedBuildFailure::ConstraintResource)?;
    constraint_work
        .charge(storage_work)
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    implementations
        .try_reserve_exact(retained_count)
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    positions
        .try_reserve(retained_count)
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)
}

/// One hidden nominal fact retained by identity without a source name binding.
#[derive(Debug, Eq, PartialEq)]
pub struct ExportedHiddenType {
    /// Stable nominal identity from the defining module.
    pub id: NominalTypeId,
    /// Whether this nominal is ordinary data or a representation-preserving newtype.
    pub declaration_kind: ResolvedNominalDeclarationKind,
    /// Number of declared parameters.
    pub parameter_count: usize,
    /// Defining constructor-family cardinality, retained independently of access.
    pub(crate) constructor_count: usize,
    /// Ordered declaration parameters, preserving defining identities.
    pub parameters: Box<[ResolvedTypeVariable]>,
    /// The canonical newtype representation template retained for linking.
    pub representation: Option<Type>,
    /// Source-aligned provenance for the canonical representation template.
    pub representation_provenance: Option<ResolvedTypeProvenance>,
    /// Complete constructor family retained without source spellings.
    pub constructors: Box<[ConstructorId]>,
    /// Access metadata retained for a name-re-exported constructor family.
    pub access: ImportedTypeAccess,
    /// Display-only declaration spelling.
    pub spelling: String,
    /// Whether the displayed declaration spelling is private at its definition.
    pub display_is_private: bool,
    /// Causal declaration provenance.
    pub origin: Origin,
}

impl ExportedHiddenType {
    fn discard_iteratively(self) {
        for parameter in self.parameters.into_vec() {
            discard_origin_iteratively(parameter.origin);
        }
        if let Some(representation) = self.representation {
            discard_type_iteratively(representation);
        }
        discard_origin_iteratively(self.origin);
    }
}

fn authenticate_identity_order<K: Copy + Eq + Hash, V>(
    facts: &HashMap<K, V>,
    order: &[K],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    constraint_work
        .charge(order.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    if facts.len() != order.len() {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    let mut seen = HashSet::new();
    seen.try_reserve(order.len())
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    for identity in order {
        if !seen.insert(*identity) || !facts.contains_key(identity) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    }
    Ok(())
}

fn map_summary_kind_failure(failure: KindFailure) -> ResolvedBuildFailure {
    match failure {
        KindFailure::Resource(_) => ResolvedBuildFailure::TypeResource,
        KindFailure::Internal(_) | KindFailure::Source(_) => ResolvedBuildFailure::InvalidState,
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum SummaryBinderOwner {
    Nominal(NominalTypeId),
    Interface(InterfaceId),
    Effect(EffectId),
    Method(MethodId),
    Global(BinderId),
    Implementation(ImplId),
}

fn register_summary_parameter<'a>(
    identity: TypeVariableId,
    kind: &'a Kind,
    owner: SummaryBinderOwner,
    origin: Span,
    environments: &mut KindEnvironments<'a>,
    type_work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    let expected_module = match owner {
        SummaryBinderOwner::Nominal(identity) => identity.module(),
        SummaryBinderOwner::Interface(identity) => identity.module(),
        SummaryBinderOwner::Effect(identity) => identity.module(),
        SummaryBinderOwner::Method(identity) => identity.interface().module(),
        SummaryBinderOwner::Global(identity) => identity
            .module()
            .ok_or(ResolvedBuildFailure::InvalidState)?,
        SummaryBinderOwner::Implementation(identity) => identity.module(),
    };
    if identity.module() != Some(expected_module) {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    if let Some((existing, _, existing_owner)) = environments.summary_declared(identity) {
        type_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::TypeResource)?;
        if existing_owner != Some(owner)
            || !same_kind_with_charge(existing, kind, || type_work.charge(1))
                .map_err(|()| ResolvedBuildFailure::TypeResource)?
        {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        return Ok(());
    }
    environments
        .insert_summary_declared(identity, kind, origin, owner, type_work)
        .map_err(map_summary_kind_failure)?;
    Ok(())
}

fn register_summary_parameters<'a>(
    parameters: &'a [ResolvedTypeVariable],
    owner: SummaryBinderOwner,
    environments: &mut KindEnvironments<'a>,
    type_work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    let mut previous = None;
    for parameter in parameters {
        if previous.is_some_and(|previous| parameter.id.local() <= previous) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        previous = Some(parameter.id.local());
        register_summary_parameter(
            parameter.id,
            &parameter.kind,
            owner,
            parameter.origin.primary_span(),
            environments,
            type_work,
        )?;
    }
    Ok(())
}

fn register_summary_scheme_parameters<'a>(
    parameters: &'a [(TypeVariableId, Kind)],
    owner: SummaryBinderOwner,
    origin: Span,
    environments: &mut KindEnvironments<'a>,
    type_work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    let mut previous = None;
    for (identity, kind) in parameters {
        if previous.is_some_and(|previous| identity.local() <= previous) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        previous = Some(identity.local());
        register_summary_parameter(*identity, kind, owner, origin, environments, type_work)?;
    }
    Ok(())
}

#[derive(Clone, Copy)]
enum SummaryRoot<'a> {
    Type(&'a Type),
    Argument(&'a crate::types::KindedArgument),
    Row(&'a EffectRow),
}
impl<'a> From<&'a Type> for SummaryRoot<'a> {
    fn from(ty: &'a Type) -> Self {
        Self::Type(ty)
    }
}
impl<'a> From<&'a crate::types::KindedArgument> for SummaryRoot<'a> {
    fn from(arg: &'a crate::types::KindedArgument) -> Self {
        Self::Argument(arg)
    }
}
impl<'a> From<&&'a Type> for SummaryRoot<'a> {
    fn from(ty: &&'a Type) -> Self {
        Self::Type(ty)
    }
}
impl<'a> From<&&'a crate::types::KindedArgument> for SummaryRoot<'a> {
    fn from(arg: &&'a crate::types::KindedArgument) -> Self {
        Self::Argument(arg)
    }
}

fn visit_summary_variables<'a>(
    root: impl Into<SummaryRoot<'a>>,
    mut charge: impl FnMut(usize) -> Result<(), ResolvedBuildFailure>,
    mut visit: impl FnMut(TypeVariableId) -> Result<(), ResolvedBuildFailure>,
) -> Result<(), ResolvedBuildFailure> {
    let mut pending = Vec::new();
    charge(1)?;
    pending
        .try_reserve(1)
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    pending.push(root.into());
    while let Some(task) = pending.pop() {
        charge(1)?;
        match task {
            SummaryRoot::Argument(crate::types::KindedArgument::TypeArg(ty)) => {
                pending.push(SummaryRoot::Type(ty))
            }
            SummaryRoot::Argument(crate::types::KindedArgument::RowArg(row)) => {
                pending.push(SummaryRoot::Row(row))
            }
            SummaryRoot::Row(row) => {
                if let Some(tail) = row.tail() {
                    let EffectRowVariable::Rigid(identity) = tail.variable() else {
                        return Err(ResolvedBuildFailure::InvalidState);
                    };
                    visit(identity)?;
                }
                for instance in row
                    .known()
                    .iter()
                    .chain(row.tail().into_iter().flat_map(|tail| tail.lacks()))
                {
                    charge(1 + instance.arguments().len())?;
                    pending
                        .try_reserve(instance.arguments().len())
                        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
                    pending.extend(instance.arguments().iter().map(SummaryRoot::Argument));
                }
            }
            SummaryRoot::Type(Type::Variable(identity)) => visit(*identity)?,
            SummaryRoot::Type(Type::Inference(_) | Type::Forall(_, _)) => {
                return Err(ResolvedBuildFailure::InvalidState);
            }
            SummaryRoot::Type(
                Type::ResourceApply(_, arguments) | Type::ForeignOwnerApply(_, arguments),
            ) => {
                charge(arguments.len())?;
                pending
                    .try_reserve(arguments.len())
                    .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
                pending.extend(arguments.iter().map(SummaryRoot::Argument));
            }
            SummaryRoot::Type(Type::Tuple(elements)) => {
                charge(elements.len())?;
                pending
                    .try_reserve(elements.len())
                    .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
                pending.extend(elements.iter().map(SummaryRoot::Type));
            }
            SummaryRoot::Type(Type::Application(left, right) | Type::Function(left, right)) => {
                charge(2)?;
                pending
                    .try_reserve(2)
                    .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
                pending.push(SummaryRoot::Type(left));
                pending.push(SummaryRoot::Type(right));
            }
            SummaryRoot::Type(Type::EffectfulFunction(domain, computation)) => {
                charge(3)?;
                pending
                    .try_reserve(3)
                    .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
                pending.push(SummaryRoot::Type(domain));
                pending.push(SummaryRoot::Type(computation.value()));
                pending.push(SummaryRoot::Row(computation.effects()));
            }
            SummaryRoot::Type(
                Type::Bytes | Type::String | Type::Int | Type::Bool | Type::Unit | Type::Nominal(_),
            ) => {}
        }
    }
    Ok(())
}

fn authenticate_summary_type_variables<'a>(
    root: impl Into<SummaryRoot<'a>>,
    parameters: impl ExactSizeIterator<Item = TypeVariableId>,
    type_work: &mut TypeWorkBudget,
) -> Result<(), ResolvedBuildFailure> {
    type_work
        .charge(parameters.len())
        .map_err(|()| ResolvedBuildFailure::TypeResource)?;
    let mut allowed = HashSet::new();
    allowed
        .try_reserve(parameters.len())
        .map_err(|_| ResolvedBuildFailure::TypeResource)?;
    allowed.extend(parameters);
    visit_summary_variables(
        root,
        |cells| {
            type_work
                .charge(cells)
                .map_err(|()| ResolvedBuildFailure::TypeResource)
        },
        |identity| {
            if allowed.contains(&identity) {
                Ok(())
            } else {
                Err(ResolvedBuildFailure::InvalidState)
            }
        },
    )
}

fn collect_summary_constraint_variables<'a>(
    root: impl Into<SummaryRoot<'a>>,
    output: &mut HashSet<TypeVariableId>,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    let mut found = Vec::new();
    visit_summary_variables(
        root,
        |cells| {
            constraint_work
                .charge(cells)
                .map_err(|()| ResolvedBuildFailure::ConstraintResource)
        },
        |identity| {
            found
                .try_reserve(1)
                .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
            found.push(identity);
            Ok(())
        },
    )?;
    constraint_work
        .charge(found.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    output
        .try_reserve(found.len())
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    output.extend(found);
    Ok(())
}

fn summary_parameter_id_set(
    parameters: impl ExactSizeIterator<Item = TypeVariableId>,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<HashSet<TypeVariableId>, ResolvedBuildFailure> {
    let parameter_count = parameters.len();
    constraint_work
        .charge(parameter_count)
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    let mut identities = HashSet::new();
    identities
        .try_reserve(parameter_count)
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    for identity in parameters {
        if !identities.insert(identity) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    }
    Ok(identities)
}

fn type_references_with_constraint_budget<'a>(
    types: &'a [crate::types::KindedArgument],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<Vec<&'a crate::types::KindedArgument>, ResolvedBuildFailure> {
    constraint_work
        .charge(types.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    let mut references = Vec::new();
    references
        .try_reserve_exact(types.len())
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    references.extend(types);
    Ok(references)
}

fn summary_selection_key_types<'a>(
    interface: &CheckedInterfaceFact,
    arguments: &'a [crate::types::KindedArgument],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<Vec<&'a crate::types::KindedArgument>, ResolvedBuildFailure> {
    if arguments.len() != interface.parameters.len() {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    let selected_count = interface
        .determination()
        .map_or(arguments.len(), |determination| {
            determination.positions().len()
        });
    let Some(determination) = interface.determination() else {
        constraint_work
            .charge(selected_count)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        let mut selected = Vec::new();
        selected
            .try_reserve_exact(selected_count)
            .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
        selected.extend(arguments);
        return Ok(selected);
    };

    let mut previous_position = None;
    for &position in determination.positions() {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if position >= arguments.len()
            || previous_position.is_some_and(|previous| previous >= position)
        {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        previous_position = Some(position);
    }
    constraint_work
        .charge(selected_count)
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    let mut selected = Vec::new();
    selected
        .try_reserve_exact(selected_count)
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    for &position in determination.positions() {
        selected.push(
            arguments
                .get(position)
                .ok_or(ResolvedBuildFailure::InvalidState)?,
        );
    }
    Ok(selected)
}

struct SummaryDeterminedApplicationSlices<'a> {
    key: Vec<&'a crate::types::KindedArgument>,
    dependents: Vec<&'a crate::types::KindedArgument>,
}

fn summary_determined_application_slices<'a>(
    interface: &CheckedInterfaceFact,
    arguments: &'a [crate::types::KindedArgument],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<Option<SummaryDeterminedApplicationSlices<'a>>, ResolvedBuildFailure> {
    if arguments.len() != interface.parameters.len() {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    let Some(determination) = interface.determination() else {
        return Ok(None);
    };
    let positions = determination.positions();
    if positions.is_empty() || positions.len() >= arguments.len() {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    constraint_work
        .charge(positions.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    let mut previous = None;
    for &position in positions {
        if position >= arguments.len() || previous.is_some_and(|previous| previous >= position) {
            return Err(ResolvedBuildFailure::InvalidState);
        }
        previous = Some(position);
    }

    constraint_work
        .charge(arguments.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    let dependent_count = arguments
        .len()
        .checked_sub(positions.len())
        .ok_or(ResolvedBuildFailure::ConstraintResource)?;
    let mut key = Vec::new();
    let mut dependents = Vec::new();
    key.try_reserve_exact(positions.len())
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;
    dependents
        .try_reserve_exact(dependent_count)
        .map_err(|_| ResolvedBuildFailure::ConstraintResource)?;

    let mut key_position = 0;
    for (position, argument) in arguments.iter().enumerate() {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if positions.get(key_position) == Some(&position) {
            key.push(argument);
            key_position += 1;
        } else {
            dependents.push(argument);
        }
    }
    if key_position != positions.len()
        || key.len() != positions.len()
        || dependents.len() != dependent_count
    {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    Ok(Some(SummaryDeterminedApplicationSlices { key, dependents }))
}

fn summary_types_are_all_bare_variables(
    types: &[&crate::types::KindedArgument],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    for ty in types {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if !matches!(ty, crate::types::KindedArgument::TypeArg(Type::Variable(_))) {
            return Ok(false);
        }
    }
    Ok(true)
}

fn summary_dependents_are_covered_by_key(
    key: &[&crate::types::KindedArgument],
    dependents: &[&crate::types::KindedArgument],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    let mut key_variables = HashSet::new();
    for ty in key {
        collect_summary_constraint_variables(ty, &mut key_variables, constraint_work)?;
    }
    let mut dependent_variables = HashSet::new();
    for ty in dependents {
        collect_summary_constraint_variables(ty, &mut dependent_variables, constraint_work)?;
    }
    constraint_work
        .charge(dependent_variables.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    Ok(dependent_variables
        .iter()
        .all(|variable| key_variables.contains(variable)))
}

fn summary_key_has_local_outer_nominal(
    key: &[&crate::types::KindedArgument],
    module: ModuleId,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    for ty in key {
        constraint_work
            .charge(2)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if (match ty {
            crate::types::KindedArgument::TypeArg(ty) => ty.outer_nominal(),
            crate::types::KindedArgument::RowArg(_) => None,
        })
        .is_some_and(|nominal| nominal.module() == module)
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn authenticate_exact_global_scheme_binders(
    scheme: &ConstrainedScheme,
    interface_facts: &HashMap<InterfaceId, &CheckedInterfaceFact>,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    let parameters = summary_parameter_id_set(
        scheme.type_parameters.iter().map(|(identity, _)| *identity),
        constraint_work,
    )?;
    let mut value_variables = HashSet::new();
    collect_summary_constraint_variables(
        scheme.value_type(),
        &mut value_variables,
        constraint_work,
    )?;
    let mut required_variables = HashSet::new();
    let mut dependent_variables = HashSet::new();
    for requirement in &scheme.requirements {
        let interface = interface_facts
            .get(&requirement.interface())
            .ok_or(ResolvedBuildFailure::InvalidState)?;
        let determined = summary_determined_application_slices(
            interface,
            requirement.arguments(),
            constraint_work,
        )?;
        if let Some(determined) = determined {
            for argument in determined.key {
                collect_summary_constraint_variables(
                    argument,
                    &mut required_variables,
                    constraint_work,
                )?;
            }
            for argument in determined.dependents {
                collect_summary_constraint_variables(
                    argument,
                    &mut dependent_variables,
                    constraint_work,
                )?;
            }
        } else {
            for argument in requirement.arguments() {
                collect_summary_constraint_variables(
                    argument,
                    &mut required_variables,
                    constraint_work,
                )?;
            }
        }
    }
    constraint_work
        .charge(required_variables.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    if required_variables
        .iter()
        .any(|identity| !value_variables.contains(identity))
    {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    constraint_work
        .charge(dependent_variables.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    let expected_count = value_variables
        .len()
        .checked_add(
            dependent_variables
                .iter()
                .filter(|identity| {
                    !required_variables.contains(identity) && !value_variables.contains(identity)
                })
                .count(),
        )
        .ok_or(ResolvedBuildFailure::ConstraintResource)?;
    if parameters.len() != expected_count {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    constraint_work
        .charge(parameters.len())
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
    for identity in &parameters {
        if !value_variables.contains(identity)
            && (!dependent_variables.contains(identity) || required_variables.contains(identity))
        {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    }
    Ok(())
}

fn authenticate_exact_implementation_head_binders(
    fact: &CheckedImplementationFact,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    let parameters = summary_parameter_id_set(
        fact.head_parameters.iter().map(|parameter| parameter.id),
        constraint_work,
    )?;
    let mut head_variables = HashSet::new();
    for argument in fact.arguments() {
        collect_summary_constraint_variables(argument, &mut head_variables, constraint_work)?;
    }
    if head_variables != parameters {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    Ok(())
}

fn authenticate_implementation_prerequisite_binders(
    fact: &CheckedImplementationFact,
    environments: &KindEnvironments<'_>,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    for prerequisite in &fact.prerequisites {
        let mut prerequisite_variables = HashSet::new();
        for argument in prerequisite.arguments() {
            collect_summary_constraint_variables(
                argument,
                &mut prerequisite_variables,
                constraint_work,
            )?;
        }
        constraint_work
            .charge(prerequisite_variables.len())
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        for identity in &prerequisite_variables {
            if !matches!(
                environments.summary_declared(*identity),
                Some((_, _, Some(SummaryBinderOwner::Implementation(owner)))) if owner == fact.id
            ) {
                return Err(ResolvedBuildFailure::InvalidState);
            }
        }
    }
    Ok(())
}

fn authenticate_scheme_parameter_mirror(
    scheme: &ConstrainedScheme,
    parameters: &[ResolvedTypeVariable],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    if scheme.type_parameters.len() != parameters.len() {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    for ((identity, kind), parameter) in scheme.type_parameters.iter().zip(parameters) {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if *identity != parameter.id
            || !same_kind_with_constraint_budget(kind, &parameter.kind, constraint_work)?
        {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    }
    Ok(())
}

fn authenticate_implementation_method_parameter_mirror(
    method: &CheckedImplementationMethodFact,
    head_parameters: &[ResolvedTypeVariable],
    method_parameters: &[ResolvedTypeVariable],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<(), ResolvedBuildFailure> {
    let expected_count = head_parameters
        .len()
        .checked_add(method_parameters.len())
        .ok_or(ResolvedBuildFailure::ConstraintResource)?;
    if method.head_type_parameter_count != head_parameters.len()
        || method.scheme.type_parameters.len() != expected_count
    {
        return Err(ResolvedBuildFailure::InvalidState);
    }
    let (scheme_head, scheme_method) = method
        .scheme
        .type_parameters
        .split_at(method.head_type_parameter_count);
    for ((identity, kind), parameter) in scheme_head.iter().zip(head_parameters) {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if *identity != parameter.id
            || !same_kind_with_constraint_budget(kind, &parameter.kind, constraint_work)?
        {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    }
    for ((identity, kind), parameter) in scheme_method.iter().zip(method_parameters) {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if *identity != parameter.id
            || !same_kind_with_constraint_budget(kind, &parameter.kind, constraint_work)?
        {
            return Err(ResolvedBuildFailure::InvalidState);
        }
    }
    Ok(())
}

fn same_kind_with_constraint_budget(
    left: &Kind,
    right: &Kind,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    same_kind_with_charge(left, right, || constraint_work.charge(1))
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)
}

fn same_origin_with_constraint_budget(
    mut left: &Origin,
    mut right: &Origin,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    loop {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        match (left, right) {
            (Origin::Source(left), Origin::Source(right)) => return Ok(left == right),
            (
                Origin::Generated {
                    cause: left_cause,
                    reason: left_reason,
                },
                Origin::Generated {
                    cause: right_cause,
                    reason: right_reason,
                },
            ) if left_reason == right_reason => {
                left = left_cause;
                right = right_cause;
            }
            (
                Origin::Related {
                    primary: left_primary,
                    related: left_related,
                },
                Origin::Related {
                    primary: right_primary,
                    related: right_related,
                },
            ) if left_related.len() == right_related.len() => {
                constraint_work
                    .charge(left_related.len())
                    .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
                if left_related != right_related {
                    return Ok(false);
                }
                left = left_primary;
                right = right_primary;
            }
            _ => return Ok(false),
        }
    }
}

fn same_origin_after_base_charge(
    mut left: &Origin,
    mut right: &Origin,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    loop {
        match (left, right) {
            (Origin::Source(left), Origin::Source(right)) => return Ok(left == right),
            (
                Origin::Generated {
                    cause: left_cause,
                    reason: left_reason,
                },
                Origin::Generated {
                    cause: right_cause,
                    reason: right_reason,
                },
            ) if left_reason == right_reason => {
                constraint_work
                    .charge(1)
                    .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
                left = left_cause;
                right = right_cause;
            }
            (
                Origin::Related {
                    primary: left_primary,
                    related: left_related,
                },
                Origin::Related {
                    primary: right_primary,
                    related: right_related,
                },
            ) if left_related.len() == right_related.len() => {
                let next_work = left_related
                    .len()
                    .checked_add(1)
                    .ok_or(ResolvedBuildFailure::ConstraintResource)?;
                constraint_work
                    .charge(next_work)
                    .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
                if left_related != right_related {
                    return Ok(false);
                }
                left = left_primary;
                right = right_primary;
            }
            _ => return Ok(false),
        }
    }
}

fn same_summary_resolved_type_variables_with_constraint_budget(
    left: &[ResolvedTypeVariable],
    right: &[ResolvedTypeVariable],
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    if left.len() != right.len() {
        return Ok(false);
    }
    for (left, right) in left.iter().zip(right) {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if left.id != right.id
            || left.spelling != right.spelling
            || !same_origin_with_constraint_budget(&left.origin, &right.origin, constraint_work)?
            || !same_kind_with_constraint_budget(&left.kind, &right.kind, constraint_work)?
        {
            return Ok(false);
        }
    }
    Ok(true)
}

fn same_resolved_type_provenance_with_constraint_budget(
    left: &ResolvedTypeProvenance,
    right: &ResolvedTypeProvenance,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    same_resolved_type_provenance_with_charge(left, right, |units| constraint_work.charge(units))
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)
}

pub(crate) fn same_resolved_type_provenance_with_budget(
    left: &ResolvedTypeProvenance,
    right: &ResolvedTypeProvenance,
    work: &mut TypeWorkBudget,
) -> Result<bool, ()> {
    same_resolved_type_provenance_with_charge(left, right, |units| work.charge(units))
}

fn same_resolved_type_provenance_with_charge(
    left: &ResolvedTypeProvenance,
    right: &ResolvedTypeProvenance,
    mut charge: impl FnMut(usize) -> Result<(), ()>,
) -> Result<bool, ()> {
    charge(1)?;
    if left.root != right.root || left.nodes.len() != right.nodes.len() {
        return Ok(false);
    }
    // Equality of two views of this exact immutable arena is reflexive. This
    // does not authenticate provenance or share a registry/Core proof. Distinct
    // arenas still compare every retained node and source identity below.
    if Arc::ptr_eq(&left.nodes, &right.nodes) {
        return Ok(true);
    }
    for (left, right) in left.nodes.iter().zip(right.nodes.iter()) {
        charge(1)?;
        match (left, right) {
            (ResolvedTypeProvenanceNode::Fact(left), ResolvedTypeProvenanceNode::Fact(right)) => {
                if left != right {
                    return Ok(false);
                }
            }
            (
                ResolvedTypeProvenanceNode::Tuple {
                    span: left_span,
                    elements: left_elements,
                },
                ResolvedTypeProvenanceNode::Tuple {
                    span: right_span,
                    elements: right_elements,
                },
            ) => {
                charge(left_elements.len())?;
                if left_span != right_span || left_elements != right_elements {
                    return Ok(false);
                }
            }
            (
                ResolvedTypeProvenanceNode::Function {
                    span: left_span,
                    domain: left_domain,
                    codomain: left_codomain,
                    effect_arguments: left_effect_arguments,
                },
                ResolvedTypeProvenanceNode::Function {
                    span: right_span,
                    domain: right_domain,
                    codomain: right_codomain,
                    effect_arguments: right_effect_arguments,
                },
            ) => {
                charge(left_effect_arguments.len())?;
                if left_span != right_span
                    || left_domain != right_domain
                    || left_codomain != right_codomain
                    || left_effect_arguments != right_effect_arguments
                {
                    return Ok(false);
                }
            }
            (
                ResolvedTypeProvenanceNode::Application {
                    span: left_span,
                    function: left_function,
                    argument: left_argument,
                    argument_span: left_argument_span,
                },
                ResolvedTypeProvenanceNode::Application {
                    span: right_span,
                    function: right_function,
                    argument: right_argument,
                    argument_span: right_argument_span,
                },
            ) => {
                if left_span != right_span
                    || left_function != right_function
                    || left_argument != right_argument
                    || left_argument_span != right_argument_span
                {
                    return Ok(false);
                }
            }
            (
                ResolvedTypeProvenanceNode::Resource {
                    span: left_span,
                    resource: left_resource,
                    arguments: left_arguments,
                },
                ResolvedTypeProvenanceNode::Resource {
                    span: right_span,
                    resource: right_resource,
                    arguments: right_arguments,
                },
            ) => {
                charge(left_arguments.len())?;
                if left_span != right_span
                    || left_resource != right_resource
                    || left_arguments != right_arguments
                {
                    return Ok(false);
                }
            }
            (
                ResolvedTypeProvenanceNode::ForeignOwner {
                    span: a,
                    nominal: x,
                    arguments: aa,
                },
                ResolvedTypeProvenanceNode::ForeignOwner {
                    span: b,
                    nominal: y,
                    arguments: bb,
                },
            ) => {
                charge(aa.len())?;
                if a != b || x != y || aa != bb {
                    return Ok(false);
                }
            }
            (
                ResolvedTypeProvenanceNode::Row {
                    span: left_span,
                    argument_roots: left_arguments,
                },
                ResolvedTypeProvenanceNode::Row {
                    span: right_span,
                    argument_roots: right_arguments,
                },
            ) => {
                charge(left_arguments.len())?;
                if left_span != right_span || left_arguments != right_arguments {
                    return Ok(false);
                }
            }
            _ => return Ok(false),
        }
    }
    Ok(true)
}

fn same_canonical_representation_with_constraint_budget(
    left_representation: Option<&Type>,
    left_provenance: Option<&ResolvedTypeProvenance>,
    right_representation: Option<&Type>,
    right_provenance: Option<&ResolvedTypeProvenance>,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    match (
        left_representation,
        left_provenance,
        right_representation,
        right_provenance,
    ) {
        (None, None, None, None) => Ok(true),
        (Some(left), Some(left_provenance), Some(right), Some(right_provenance)) => Ok(
            same_type_with_constraint_budget(left, right, constraint_work)
                .map_err(|_| ResolvedBuildFailure::ConstraintResource)?
                && same_resolved_type_provenance_with_constraint_budget(
                    left_provenance,
                    right_provenance,
                    constraint_work,
                )?,
        ),
        _ => Ok(false),
    }
}

fn same_checker_type_variable_after_base_charge(
    left: &ResolvedTypeVariable,
    right: &ResolvedTypeVariable,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    if left.id != right.id || left.spelling != right.spelling {
        return Ok(false);
    }
    if !same_origin_with_constraint_budget(&left.origin, &right.origin, constraint_work)? {
        return Ok(false);
    }
    same_kind_with_constraint_budget(&left.kind, &right.kind, constraint_work)
}

fn same_constrained_schemes_with_constraint_budget(
    left: &ConstrainedScheme,
    right: &ConstrainedScheme,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    if left.type_parameters.len() != right.type_parameters.len()
        || left.requirements.len() != right.requirements.len()
    {
        return Ok(false);
    }
    for ((left_identity, left_kind), (right_identity, right_kind)) in left
        .type_parameters
        .iter()
        .zip(right.type_parameters.iter())
    {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if left_identity != right_identity
            || !same_kind_with_constraint_budget(left_kind, right_kind, constraint_work)?
        {
            return Ok(false);
        }
    }
    for (left, right) in left.requirements.iter().zip(right.requirements.iter()) {
        constraint_work
            .charge(1)
            .map_err(|()| ResolvedBuildFailure::ConstraintResource)?;
        if left.id != right.id
            || left.span != right.span
            || !same_origin_with_constraint_budget(&left.origin, &right.origin, constraint_work)?
            || !same_interface_application_with_constraint_budget(
                left.application(),
                right.application(),
                constraint_work,
            )?
        {
            return Ok(false);
        }
    }
    same_type_with_constraint_budget(left.value_type(), right.value_type(), constraint_work)
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)
}

fn same_interface_application_with_constraint_budget(
    left: &InterfaceApplication,
    right: &InterfaceApplication,
    constraint_work: &mut crate::interface::InterfaceConstraintBudget,
) -> Result<bool, ResolvedBuildFailure> {
    if left.interface() != right.interface() || left.arguments().len() != right.arguments().len() {
        return Ok(false);
    }
    for (left, right) in left.arguments().iter().zip(right.arguments()) {
        if !crate::interface::same_kinded_argument_with_constraint_budget(
            left,
            right,
            constraint_work,
        )
        .map_err(|()| ResolvedBuildFailure::ConstraintResource)?
        {
            return Ok(false);
        }
    }
    Ok(true)
}

