/// The closed resolved expression family.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ResolvedExprKind {
    /// A decoded UTF-8 string literal.
    String(String),
    /// A cleanup owner around a body and its ordinary completion call.
    Cleanup(Box<ResolvedCleanupExpr>),
    /// An arbitrary-precision integer literal.
    Integer(Integer),
    /// A Boolean literal.
    Boolean(bool),
    /// The unit value.
    Unit,
    /// A resolved name occurrence.
    Occurrence(ResolvedOccurrence),
    /// A resolved constructor term occurrence.
    Constructor(ResolvedConstructorOccurrence),
    /// A strict structural tuple.
    Tuple(Vec<ResolvedExpr>),
    /// Strict unary application.
    Apply(ResolvedApplicationExpr),
    /// Integer addition.
    Add(ResolvedBinaryExpr),
    /// Integer multiplication.
    Multiply(ResolvedBinaryExpr),
    /// Integer equality.
    Equal(ResolvedBinaryExpr),
    /// A sequential block expression.
    Block(ResolvedBlock),
    /// An anonymous unary function.
    Function(ResolvedFunctionExpr),
    /// A structured match.
    Match(ResolvedMatchExpr),
    /// One exact operation request.
    Perform(ResolvedPerformExpr),
    /// A lexical handler for one exact effect instance.
    Handle(ResolvedHandleExpr),
    /// A use of the nearest clause-scoped resume capability.
    Resume(ResolvedResumeExpr),
    /// Nullary consumption of the enclosing clause capability.
    Discard(ResolvedDiscardExpr),
    /// A scoped resource acquisition with a rigid, nongeneralized identity.
    Resource(Box<ResolvedResourceExpr>),
    /// An explicit checked foreign host with one fresh lexical identity.
    ForeignHost(Box<ResolvedForeignHostExpr>),
    /// A fresh finite access window; resolution supplies no executable permission.
    CopyWindow(Box<ResolvedCopyWindowExpr>),
    /// An experimental source-defined resource instance.
    ProviderResource(Box<ResolvedProviderResourceExpr>),
}

