    use crate::types::KindedArgument;
    #[test]
    fn body_free_resource_kind_authenticates_canonical_category_and_identity_slot() {
        // Compiler-private kind fixture, not source admission or resource
        // lifecycle acceptance. Independent defining signature checks have
        // their own mutation tests above.
        let source = SourceFile::new("resource-kind.ash", "owner").unwrap();
        let span = source.span(ByteRange::new(0, 5).unwrap()).unwrap();
        let module = ModuleId::from(source.id());
        let mixed = ResourceDefinitionId::new(module, 0);
        let ordinary = ResourceDefinitionId::new(module, 1);
        let malformed = ResourceDefinitionId::new(module, 2);
        let mixed_family = NominalTypeId::new(module, 0);
        let ordinary_family = NominalTypeId::new(module, 1);
        let malformed_family = NominalTypeId::new(module, 2);
        let parameters = [
            ResolvedTypeVariable {
                id: TypeVariableId::resolved(module, 0),
                spelling: "S".into(),
                kind: Kind::Type,
                origin: Origin::Source(span),
            },
            ResolvedTypeVariable {
                id: TypeVariableId::resolved(module, 1),
                spelling: "E".into(),
                kind: Kind::EffectRow,
                origin: Origin::Source(span),
            },
        ];
        let mut work = TypeWorkBudget::unbounded();
        let canonical = clone_resolved_type_variables_with_budget(&parameters, &mut work).unwrap();
        let mut registry = ResolvedRegistry::default().with_additional_type_variables(canonical);
        for (id, family, formals) in [
            (mixed, mixed_family, parameters.as_slice()),
            (ordinary, ordinary_family, &parameters[..1]),
            (malformed, malformed_family, &parameters[1..]),
        ] {
            registry
                .retain_owner_signature(OwnerId::Resource(id), Some(family), formals, &mut work)
                .unwrap();
            registry.abstract_nominal_kinds.insert(
                family,
                NonMaterializedNominalKindFact {
                    kind: NonMaterializedNominalKind::for_resource(id, formals, &mut work).unwrap(),
                    origin: span,
                },
            );
        }
        let mut environments = crate::kind::KindEnvironments::new_with_registry(&registry);
        environments
            .insert_row_resource_family(mixed_family, mixed, &parameters, span, &mut work)
            .unwrap();
        environments
            .insert_row_resource_family(
                malformed_family,
                malformed,
                &parameters[1..],
                span,
                &mut work,
            )
            .unwrap();
        let Some(CanonicalNominalKind::Frozen { kind, .. }) =
            registry.nominal_kind(ordinary_family)
        else {
            panic!("ordinary constructor kind retained")
        };
        environments
            .insert_frozen_nominal(ordinary_family, kind, span, &mut work)
            .unwrap();
        let proper = Type::ResourceApply(
            mixed,
            vec![
                KindedArgument::TypeArg(Type::Unit),
                KindedArgument::RowArg(EffectRow::empty()),
            ]
            .into_boxed_slice(),
        );
        let mut exact = TypeWorkBudget::unbounded();
        assert_eq!(
            environments
                .synthesize_body_free_kind(&proper, span, &mut exact)
                .unwrap(),
            &Kind::Type
        );
        let total = exact.used();
        assert_eq!(
            environments
                .synthesize_body_free_kind(&proper, span, &mut TypeWorkBudget::with_limit(total))
                .unwrap(),
            &Kind::Type
        );
        assert!(
            environments
                .synthesize_body_free_kind(
                    &proper,
                    span,
                    &mut TypeWorkBudget::with_limit(total - 1)
                )
                .unwrap_err()
                .is_resource_exhaustion()
        );
        for forged in [
            Type::ResourceApply(
                ordinary,
                vec![KindedArgument::TypeArg(Type::Unit)].into_boxed_slice(),
            ),
            Type::ResourceApply(
                malformed,
                vec![KindedArgument::RowArg(EffectRow::empty())].into_boxed_slice(),
            ),
            Type::ResourceApply(
                mixed,
                vec![
                    KindedArgument::TypeArg(Type::Unit),
                    KindedArgument::TypeArg(Type::Unit),
                ]
                .into_boxed_slice(),
            ),
            Type::ResourceApply(mixed, Box::new([])),
            Type::Nominal(mixed_family),
            Type::Application(Box::new(Type::Nominal(mixed_family)), Box::new(Type::Unit)),
        ] {
            let failure = environments
                .synthesize_body_free_kind(&forged, span, &mut work)
                .unwrap_err();
            assert!(!failure.is_resource_exhaustion());
            assert!(!failure.is_source_rejection());
        }
        let ordinary_application = Type::Application(
            Box::new(Type::Nominal(ordinary_family)),
            Box::new(Type::Unit),
        );
        assert_eq!(
            environments
                .synthesize_body_free_kind(&ordinary_application, span, &mut work)
                .unwrap(),
            &Kind::Type
        );
        assert_eq!(
            environments
                .synthesize_body_free_kind(&Type::Nominal(ordinary_family), span, &mut work)
                .unwrap(),
            kind
        );
    }

    #[test]
    fn owner_signature_coverage_refuses_surplus_empty_owners_and_corrupt_indexes() {
        let source = SourceFile::new("owner-coverage.ash", "owner").unwrap();
        let module = ModuleId::from(source.id());
        let first = EffectId::new(module, 0);
        let second = EffectId::new(module, 1);
        let extra = InterfaceId::new(module, 0);
        let expected = [OwnerId::Effect(first), OwnerId::Effect(second)];
        let mut work = TypeWorkBudget::unbounded();
        let mut registry = ResolvedRegistry::default();
        registry
            .authenticate_owner_signature_coverage([], &mut work)
            .unwrap();
        for owner in expected {
            registry
                .retain_owner_signature(owner, None, &[], &mut work)
                .unwrap();
        }
        registry
            .authenticate_owner_signature_coverage(expected, &mut work)
            .unwrap();
        registry.owner_signatures.effect_positions.insert(first, 1);
        registry.owner_signatures.effect_positions.insert(second, 0);
        assert_eq!(
            registry.authenticate_owner_signature_coverage(expected, &mut work),
            Err(ResolvedBuildFailure::InvalidState)
        );
        registry.owner_signatures.effect_positions.insert(first, 0);
        registry.owner_signatures.effect_positions.insert(second, 1);
        registry
            .retain_owner_signature(OwnerId::Interface(extra), None, &[], &mut work)
            .unwrap();
        assert_eq!(
            registry.authenticate_owner_signature_coverage(expected, &mut work),
            Err(ResolvedBuildFailure::InvalidState)
        );
        // The same empty, unassociated interface is legitimate when its
        // independently retained defining fact belongs to the consuming view.
        let complete = expected.into_iter().chain([OwnerId::Interface(extra)]);
        registry
            .authenticate_owner_signature_coverage(complete, &mut work)
            .unwrap();
        registry
            .owner_signatures
            .interface_positions
            .insert(InterfaceId::new(module, 1), 0);
        assert_eq!(
            registry.authenticate_owner_signature_coverage(
                expected.into_iter().chain([OwnerId::Interface(extra)]),
                &mut work
            ),
            Err(ResolvedBuildFailure::InvalidState)
        );
    }

    #[test]
    fn owner_signature_authentication_keeps_defining_order_kind_and_family_independent() {
        let source = SourceFile::new("owner-signature.ash", "owner").unwrap();
        let span = source.span(ByteRange::new(0, 5).unwrap()).unwrap();
        let module = ModuleId::from(source.id());
        let resource = ResourceDefinitionId::new(module, 0);
        let family = NominalTypeId::new(module, 0);
        let definition = [
            ResolvedTypeVariable {
                id: TypeVariableId::resolved(module, 0),
                spelling: "S".into(),
                kind: Kind::Type,
                origin: Origin::Source(span),
            },
            ResolvedTypeVariable {
                id: TypeVariableId::resolved(module, 1),
                spelling: "E".into(),
                kind: Kind::EffectRow,
                origin: Origin::Source(span),
            },
        ];
        let mut work = TypeWorkBudget::unbounded();
        let canonical = clone_resolved_type_variables_with_budget(&definition, &mut work).unwrap();
        let mut registry = ResolvedRegistry::default().with_additional_type_variables(canonical);
        let owner = OwnerId::Resource(resource);
        registry
            .retain_owner_signature(owner, Some(family), &definition, &mut work)
            .unwrap();
        registry
            .authenticate_owner_signature(owner, Some(family), &definition, &mut work)
            .unwrap();
        let index = registry.owner_signatures.resource_positions[&resource];
        registry.owner_signatures.resources[index]
            .1
            .parameters
            .swap(0, 1);
        assert_eq!(
            registry.authenticate_owner_signature(owner, Some(family), &definition, &mut work),
            Err(ResolvedBuildFailure::InvalidState)
        );
        registry.owner_signatures.resources[index]
            .1
            .parameters
            .swap(0, 1);
        // The table-facing variable and a second retained mirror agree on the
        // forged kind. The original declaration stays untouched.
        let mut forged = clone_resolved_type_variables_with_budget(&definition, &mut work).unwrap();
        forged[1].kind = Kind::Type;
        registry
            .type_variables
            .get_mut(&definition[1].id)
            .unwrap()
            .kind = Kind::Type;
        registry
            .authenticate_owner_signature(owner, Some(family), &forged, &mut work)
            .unwrap();
        assert_eq!(
            registry.authenticate_owner_signature(owner, Some(family), &definition, &mut work),
            Err(ResolvedBuildFailure::InvalidState)
        );
        registry
            .type_variables
            .get_mut(&definition[1].id)
            .unwrap()
            .kind = Kind::EffectRow;
        registry.owner_signatures.resources[index].0 = NominalTypeId::new(module, 1);
        assert_eq!(
            registry.authenticate_owner_signature(owner, Some(family), &definition, &mut work),
            Err(ResolvedBuildFailure::InvalidState)
        );
        registry.owner_signatures.resources[index].0 = family;
        registry
            .authenticate_owner_signature(owner, Some(family), &definition, &mut work)
            .unwrap();
        // Eligibility of ordinary effect/interface signatures has no resource
        // association prerequisite.
        for owner in [
            OwnerId::Effect(EffectId::new(module, 0)),
            OwnerId::Interface(InterfaceId::new(module, 0)),
        ] {
            registry
                .retain_owner_signature(owner, None, &definition, &mut work)
                .unwrap();
            registry
                .authenticate_owner_signature(owner, None, &definition, &mut work)
                .unwrap();
        }
        assert_eq!(
            registry.authenticate_owner_signature(
                owner,
                Some(family),
                &definition,
                &mut TypeWorkBudget::with_limit(0)
            ),
            Err(ResolvedBuildFailure::TypeResource)
        );
    }

    #[test]
    fn resource_constructor_categories_do_not_fabricate_a_row_kind_arrow() {
        let source = SourceFile::new("resource-category.ash", "owner").unwrap();
        let span = source.span(ByteRange::new(0, 5).unwrap()).unwrap();
        let module = ModuleId::from(source.id());
        let id = ResourceDefinitionId::new(module, 0);
        let mut parameters = [ResolvedTypeVariable {
            id: TypeVariableId::resolved(module, 0),
            spelling: "F".into(),
            kind: Kind::Arrow(Box::new(Kind::Type), Box::new(Kind::Type)),
            origin: Origin::Source(span),
        }];
        let mut work = TypeWorkBudget::unbounded();
        let ordinary =
            NonMaterializedNominalKind::for_resource(id, &parameters, &mut work).unwrap();
        let NonMaterializedNominalKind::Ordinary(kind) = ordinary else {
            panic!("row-free resource preserves its constructor kind")
        };
        assert_eq!(
            kind,
            Kind::Arrow(Box::new(parameters[0].kind.clone()), Box::new(Kind::Type))
        );
        parameters[0].kind = Kind::EffectRow;
        assert_eq!(
            NonMaterializedNominalKind::for_resource(id, &parameters, &mut work).unwrap(),
            NonMaterializedNominalKind::RowBearingResource(id)
        );
        assert!(
            NonMaterializedNominalKind::for_resource(
                id,
                &parameters,
                &mut TypeWorkBudget::with_limit(0)
            )
            .is_err()
        );
    }

    #[test]
    fn summary_overlap_retains_kind_context() {
        let source = crate::source::SourceFile::new("cause.ash", "binder").unwrap();
        let span = source
            .span(crate::source::ByteRange::new(0, 6).unwrap())
            .unwrap();
        let kind = Kind::Type;
        let mut environments = crate::kind::KindEnvironments::new();
        let identity = TypeVariableId::new(0);
        environments
            .insert_declared(identity, &kind, span, &mut TypeWorkBudget::with_limit(1))
            .unwrap();
        let failure = environments
            .insert_declared(identity, &kind, span, &mut TypeWorkBudget::with_limit(1))
            .unwrap_err();
        let context = failure.internal_context().unwrap();
        assert_eq!(
            map_summary_overlap_result(Err(OverlapFailure::Kind(context))),
            Err(ResolvedBuildFailure::Kind(context))
        );
        for (overlap, summary) in [
            (
                OverlapFailure::Resource,
                ResolvedBuildFailure::ConstraintResource,
            ),
            (
                OverlapFailure::TypeResource,
                ResolvedBuildFailure::TypeResource,
            ),
            (
                OverlapFailure::InvalidState,
                ResolvedBuildFailure::InvalidState,
            ),
        ] {
            assert_eq!(map_summary_overlap_result(Err(overlap)), Err(summary));
        }
    }
    use super::*;

    fn capture_method_fixture() -> ResolvedImplementationMethodGroup {
        let file = SourceFile::new("capture-work.ash", "x + x + y").expect("source");
        let module = ModuleId::new(42_005);
        let span = file
            .span(ByteRange::new(0, 9).expect("range"))
            .expect("span");
        let occurrence = |ordinal, spelling: &str, start| ResolvedExpr {
            kind: ResolvedExprKind::Occurrence(ResolvedOccurrence {
                term: ResolvedTermName::Global(BinderId::resolved(module, ordinal)),
                spelling: spelling.to_owned(),
                origin: Origin::Source(
                    file.span(ByteRange::new(start, start + 1).expect("range"))
                        .expect("span"),
                ),
                import_span: None,
                evidence: Box::new([]),
            }),
            span: file
                .span(ByteRange::new(start, start + 1).expect("range"))
                .expect("span"),
        };
        let add = |left, right| ResolvedExpr {
            kind: ResolvedExprKind::Add(ResolvedBinaryExpr {
                left: Box::new(left),
                right: Box::new(right),
                operator_span: span,
            }),
            span,
        };
        let binder = Binder {
            id: BinderId::resolved(module, 3),
            spelling: "read".to_owned(),
            origin: Origin::Source(span),
        };
        ResolvedImplementationMethodGroup {
            contextual_parameters: Box::new([]),
            method: Some(MethodId::new(InterfaceId::new(module, 0), 0)),
            identity: None,
            binder: binder.clone(),
            equations: Box::new([ResolvedEquation {
                name: ResolvedEquationHead {
                    binder: binder.id,
                    spelling: binder.spelling,
                    origin: binder.origin,
                },
                patterns: vec![ResolvedPattern {
                    kind: ResolvedPatternKind::Binder(Binder {
                        id: BinderId::resolved(module, 2),
                        spelling: "ignored".to_owned(),
                        origin: Origin::Source(span),
                    }),
                    span,
                }],
                body: add(
                    add(occurrence(0, "x", 0), occurrence(0, "x", 4)),
                    occurrence(1, "y", 8),
                ),
                span,
            }]),
            span,
        }
    }

    #[test]
    fn lexical_capture_occurrences_preserve_walk_order_and_duplicate_sites() {
        let group = capture_method_fixture();
        let ResolvedExprKind::Add(outer) = &group.equations[0].body.kind else {
            panic!("outer addition");
        };
        let ResolvedExprKind::Add(inner) = &outer.left.kind else {
            panic!("inner addition");
        };
        let expected = [&outer.right, &inner.right, &inner.left].map(|expression| {
            let ResolvedExprKind::Occurrence(occurrence) = &expression.kind else {
                panic!("capture occurrence");
            };
            occurrence
        });
        let captures = lexical_method_capture_occurrences(&group, &mut TypeWorkBudget::default())
            .expect("capture walk");
        assert_eq!(captures.len(), 3);
        for (actual, expected) in captures.iter().zip(expected) {
            assert!(
                std::ptr::eq(*actual, expected),
                "retain each original occurrence in stack traversal order"
            );
        }
        let module = ModuleId::new(42_005);
        assert_eq!(
            lexical_method_captures(&group, &mut TypeWorkBudget::default())
                .expect("capture binders")
                .as_ref(),
            &[
                BinderId::resolved(module, 1),
                BinderId::resolved(module, 0),
                BinderId::resolved(module, 0)
            ]
        );
    }

    #[test]
    fn lexical_capture_pattern_seed_has_an_exact_retryable_boundary() {
        // Equation slot, pattern seed, pattern visit, five expression visits,
        // and three occurrence-filter cells for read ignored = x + x + y.
        const WORK: usize = 1 + 1 + 1 + 5 + 3;
        let group = capture_method_fixture();
        let mut short = TypeWorkBudget::with_limit(WORK - 1);
        assert_eq!(
            lexical_method_capture_occurrences(&group, &mut short),
            Err(())
        );
        for _ in 0..2 {
            let mut exact = TypeWorkBudget::with_limit(WORK);
            assert_eq!(
                lexical_method_capture_occurrences(&group, &mut exact)
                    .expect("fresh exact capture walk")
                    .len(),
                3
            );
            assert_eq!(exact.used(), WORK);
        }
    }

